(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ru"] = {"ui":{"skip":"Перейти к содержимому","back":"← Назад к AI-gile","lang.button":"Язык: {name}","lang.dialog":"Выбери язык","lang.search":"Найти язык","lang.none":"Подходящих языков нет","lang.notYet":"{name} пока не переведён","theme.aria":"Сменить тему: светлая, тёмная или чёрная","theme.toLight":"Включить светлую тему","theme.toDark":"Включить тёмную тему","theme.toBlack":"Включить чёрную тему (настоящий чёрный, бережёт OLED-экраны)","words.underline":"Подчеркнуть эти слова на странице","words.underlineHelp":"Наведи курсор на слово с пунктирным подчёркиванием или нажми на него, чтобы узнать, что оно значит.","words.col.todo":"Карточки, выбранные на сейчас: команда возьмётся за них следующими.","words.col.doing":"Сейчас над этой карточкой работает ИИ.","words.col.review":"Один ИИ закончил работу; другой проверяет её, прежде чем она дойдёт до тебя.","words.col.verify":"Ждёт тебя: попробуй и скажи, работает ли.","words.col.team":"Твои заметки или ответы, которые ждут, пока команда их подхватит.","words.col.done":"Готово и принято.","index.title":"AI-gile: твоя команда ИИ-разработчиков на одной доске","index.description":"AI-gile это канбан-доска для команд ИИ-программистов. Они работают, пока ты спишь, а тебе остаётся одна короткая стопка: что решить, что проверить и что принять.","hero.logoAlt":"Значок доски AI-gile","hero.h1.html":"Твоя команда ИИ-разработчиков на одной&nbsp;доске.","hero.alpha":"🐣 Закрытая пре-альфа","hero.alphaTitle":"Ещё сыро и не закончено: спасибо, что пробуешь!","hero.lede":"Они строят, пока ты спишь. Утром тебя ждёт одна короткая стопка: пара вопросов, пара вещей на проверку, один-два фиолетовых ромбика. Клик, принял, и обратно к кофе.","dl.windows":"Приложение для Windows","dl.browser":"Запустить в браузере","dl.messenger":"📱 Messenger для телефона","dl.soon":"Скоро","dl.notify":"🔔 Напиши, когда откроется","dl.notifySmall":"Альфа или бета","hero.secondary":"Agile, только команде не нужен кофе на стендапе. (Стендапы они всё равно проводят.)","pitch.h2":"AI-gile в любом количестве слов","pitch.lede":"Выбери длину: от одного слова до 144. Каждая длина это отдельное описание, написанное именно под неё. Двигай ползунок или жми стрелки.","pitch.rangeLabel":"Длина в словах","pitch.dice":"🎲 другой вариант","pitch.words.one":"{n} слово","pitch.words.other":"{n} слова","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} буквы","pitch.chars.one":"{n} символ","pitch.chars.other":"{n} символа","count.line.html.one":"{n} карточка на доске прямо сейчас","count.line.html.other":"{n} карточки на доске прямо сейчас","people.humans.html.one":"👥 {n} человек","people.humans.html.other":"👥 {n} человек","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агентов","people.working.html.one":"⚡ {n} в работе прямо сейчас","people.working.html.other":"⚡ {n} в работе прямо сейчас","pre.title":"AI-gile: здесь что-то строится","pre.description":"Здесь что-то строится: доска, на которой ИИ-команды строят то, что ты просишь, и по ходу дела учат тебя. Пока что закрытая пре-альфа для друзей.","pre.h1":"Здесь что-то строится. 🤫","pre.line":"Доска, на которой ИИ-команды строят то, что ты просишь, и по ходу дела учат тебя. Пока что закрытая пре-альфа для друзей.","pre.btn":"🔔 Напиши, когда откроется","pre.peek":"За стеклом: настоящая доска, вживую. Каждая карточка — цветная полоска.","pre.peekFake":"За стеклом: так выглядит доска в работе.","pre.night":"🌙 Ночной сторож за главного · 😴 человек отдыхает","features.aria":"Что она делает","f.pile.h":"Одна стопка для тебя","f.pile.html":"<b>Тебе</b> собирает всё, что ждёт тебя, из всех проектов: вопросы, вещи на проверку, задачи, которые под силу только человеку. Твоя очередь подскажет, что дальше и сколько это займёт.","f.sleep.h":"Команды, которые работают, пока ты спишь","f.sleep.p":"У каждого проекта есть лид и команда ИИ-агентов. Оставь комментарий к карточке, команда проснётся, сделает работу и вернёт её с шагами, которые осилит даже уставший человек.","f.tester.h":"Сначала проверяет ИИ-тестировщик","f.tester.p":"Прежде чем что-то дойдёт до тебя, тестировщик проходит шаги в копии приложения и показывает, что увидел, со скриншотом. Пролистай прошедшее проверку и прими одним кликом.","f.proof.h":"Доказательства, а не обещания","f.proof.p":"Каждая сдача показывает, что изменилось: файлы, diff, скриншоты. Не нужно открывать каждое приложение, чтобы узнать, готово ли оно.","f.chat.h":"Общайся со своими лидами","f.chat.p":"Боковая панель как в Discord: по значку на проект, фиолетовые ромбики там, где нужен ты. Напиши лиду идею, и он превратит её в карточки и план, а тебе останется кнопка ✅ Go.","f.tidy.h":"Сама наводит порядок","f.tidy.p":"Похожие карточки сливаются в одну, запутанные названия исправляются, а проверка токенов следит, чтобы код не разбухал. Меньше переключений, меньше лишних мыслей.","f.private.h":"Твоя, на твоём компьютере","f.private.li1":"Доска работает на твоём компьютере и отвечает только тебе.","f.private.li2":"Личные сообщения между людьми защищены сквозным шифрованием.","f.private.li3":"Никаких аккаунтов, трекеров и cookie.","f.lang.h":"На твоём языке","f.lang.p":"Больше 120 языков: от нидерландского, валлийского и японского до пиратского, языка Йоды и клингонского, и быстрый переход на английский для профессионального жаргона.","f.service.h":"От идеи до настоящего сервиса","f.service.p":"Сделал с ИИ что-то, чем теперь пользуются люди? Отметь это как сервис, и доска поможет вести его как следует: проверки доступности, публичная страница статуса, инциденты с разбором, изменения, которым нужно Go, ежедневная проверка резервных копий. Справка объясняет каждый шаг по ходу дела.","msgr.h2":"AI-gile Messenger: твоя команда в кармане","msgr.p1":"Общайся со своей ИИ-командой, не открывая доску. Переписывайся с лидами проектов и друзьями, смотри шаги проверки карточки и отвечай на них, всё с телефона.","msgr.p2":"Чтобы связать его с доской, отсканируй на ней QR-код. Впервые? Дружелюбный демо-чат всё покажет.","msgr.when":"Сначала Android, потом веб-версия для телефонов и iPhone.","msgr.who":"Твой лид проекта","msgr.b1":"Исправление тёмной темы готово. Прислать шаги проверки?","msgr.b2":"Да, пожалуйста!","msgr.b3":"1. Открой Настройки. 2. Выбери Тёмную. Всё выглядит как надо?","tl.aria":"Хронология от первого разговора до дорожной карты","tl.h2":"От первого разговора до того, что дальше","tl.lede":"Настоящие даты и время в твоём часовом поясе. После сегодняшнего дня идёт план, без обещанных дат.","tl.today":"Сегодня","tl.planned":"в планах","tl.doing":"в работе","tl.cards.one":"{n} карточка","tl.cards.other":"{n} карточки","join.h2":"Присоединяйся","join.lede":"AI-gile строят бородатый чудак с AuDHD и несколькими битвами за психическое здоровье — и множество терпеливых агентов. Пока всё закрыто: закрытая альфа для друзей. Хочешь попробовать, когда откроется?","join.btn":"Оставить заявку","join.small":"Напишем на почту, и больше ничего","footer.tag":"AI-gile. Без трекеров, без cookie, без кофе на стендапе.","footer.licence":"Лицензия для бизнеса","footer.status":"Статус","footer.privacy":"Что мы храним","footer.thanks":"Звонки благодаря ChilledChat","form.sending":"Отправляю…","form.failed":"Не вышло: попробуй позже.","form.offline":"Не удалось связаться с AI-gile: попробуй позже.","form.keep":"Мы используем это только чтобы ответить тебе, а потом удаляем. Без трекеров и cookie.","form.keepLink":"Что мы храним","interest.title":"AI-gile: напиши мне, когда откроется альфа","interest.description":"Оставь почту, чтобы узнать, когда откроется закрытая альфа или бета AI-gile.","interest.h1":"🔔 Напиши, когда откроется","interest.lede":"AI-gile в закрытой пре-альфе. Оставь почту, и мы напишем один раз, когда для тебя найдётся место.","interest.email":"Твоя почта","interest.which":"Какой тест?","interest.alpha":"Закрытая альфа: рано, сыро, много изменений","interest.beta":"Бета: стабильнее, позже","interest.both":"Любой, что раньше","interest.submit":"Внесите меня в список","interest.thanks":"Спасибо! Ты в списке.","licence.title":"AI-gile: лицензия для бизнеса","licence.description":"Используешь AI-gile в бизнесе? Подай заявку на бесплатную лицензию.","licence.h1":"📜 Лицензия для бизнеса","licence.lede":"Используешь AI-gile на работе? Расскажи, кто ты и чем занимаешься. Если это приносит пользу, лицензия бесплатна.","licence.company":"Компания","licence.website":"Сайт","licence.what":"Чем занимаешься","licence.how":"Чем это помогает миру","licence.email":"Почта","licence.submit":"Отправить заявку","licence.thanks":"Спасибо! Ответим по почте.","status.title":"Статус AI-gile","status.h1":"Статус AI-gile","status.quiet":"Всё тихо","status.intro":"AI-gile сейчас работает? Эта страница каждые 5 минут проверяет сайт, общий доступ к доскам, звонки и загрузку.","status.up":"Работает (ответ за {ms} мс)","status.slow":"Не ответил при последней проверке, пробую снова","status.down":"Не работает: не ответил на две последние проверки","status.svc.web":"Сайт","status.svc.web.offers":"Этот сайт: что такое AI-gile, и форма записи в список","status.svc.boards":"Общий доступ к доскам","status.svc.boards.offers":"Публичные доски, сообщения между друзьями и приглашения","status.svc.calls":"Звонки","status.svc.calls.offers":"Голос, видео и демонстрация экрана в AI-gile","status.svc.download":"Загрузка","status.svc.download.offers":"Установщик для Windows и ссылки-приглашения","status.checking":"Проверяю…","status.offline":"Сейчас не получается связаться со службой статуса (пробую снова)","status.updated":"обновлено {ago}","status.justNow":"только что","status.min":"{n} мин назад","status.hours":"{n} ч назад","status.days":"{n} д назад","privacy.title":"AI-gile: что мы храним","privacy.h1":"Что мы храним","privacy.lede":"Коротко: только то, что ты нам отправишь, и ненадолго.","privacy.only":"Только то, что ты нам отправляешь: то, что вводишь в форму, например свою почту. Больше ничего о тебе.","privacy.sealed":"Всё запечатывается, так что наш сервер не может это прочитать: прямо в твоём браузере, ещё до отправки (в старом браузере — в момент получения). Открыть это может только наша собственная доска.","privacy.server":"С сервера это удаляется, как только попадает на нашу доску. Всё, что пролежит там дольше 30 дней, удаляется в любом случае.","privacy.board":"На нашей доске мы храним это только до тех пор, пока не ответим тебе, а потом удаляем и оттуда.","privacy.none":"Без трекеров, без cookie, без аналитики.","privacy.local":"Твой язык и выбор светлой или тёмной темы остаются в твоём браузере. Нам они никогда не отправляются.","privacy.ask":"Хочешь, чтобы это удалили раньше? Ответь на наше письмо и скажи об этом.","live.h2":"Смотрите, как это строится, в прямом эфире","live.caption":"Каждая карточка скрыта: вы видите форму работы, а не слова.","live.watching.one":"в эфире: смотрит {n}","live.watching.other":"в эфире: смотрят {n}","live.last.now":"Последняя карточка перемещена только что","live.last.min.one":"Последняя карточка перемещена {n} минуту назад","live.last.min.other":"Последняя карточка перемещена {n} минуты назад","live.last.hour.one":"Последняя карточка перемещена {n} час назад","live.last.hour.other":"Последняя карточка перемещена {n} часа назад","live.last.day.one":"Последняя карточка перемещена {n} день назад","live.last.day.other":"Последняя карточка перемещена {n} дня назад","live.offline":"Живая доска немного отдыхает. Загляните позже.","live.cols":"Бэклог|К выполнению|В работе|Команда проверяет|Тебе на тест|Для команды|Готово","pitch.words.few":"{n} слова","pitch.words.many":"{n} слов","pitch.letters.few":"{n} буквы","pitch.letters.many":"{n} букв","pitch.chars.few":"{n} символа","pitch.chars.many":"{n} символов","count.line.html.few":"{n} карточки на доске прямо сейчас","count.line.html.many":"{n} карточек на доске прямо сейчас","tl.cards.few":"{n} карточки","tl.cards.many":"{n} карточек","live.last.min.few":"Последняя карточка перемещена {n} минуты назад","live.last.min.many":"Последняя карточка перемещена {n} минут назад","live.last.hour.few":"Последняя карточка перемещена {n} часа назад","live.last.hour.many":"Последняя карточка перемещена {n} часов назад","live.last.day.few":"Последняя карточка перемещена {n} дня назад","live.last.day.many":"Последняя карточка перемещена {n} дней назад","footer.models":"AI-gile запускает ИИ-модели, которые работают за тебя. То, что они говорят и делают, на их совести, так что проверяй, прежде чем доверять.","privacy.ai.h":"Часть про ИИ","privacy.ai.models":"AI-gile это доска. Работу делают ИИ-модели других компаний, такие как Claude, Codex и Gemini, на твоих собственных аккаунтах.","privacy.ai.check":"То, что они пишут и делают, идёт от них и может быть неверным. Проверяй, прежде чем полагаться на это или выпускать.","privacy.ai.files":"Они меняют файлы и запускают команды в папках, которые ты подключаешь. Сделай резервную копию.","privacy.ai.send":"То, что ты даёшь модели, уходит компании, которая её запускает, на её условиях. Действуют собственные условия и расценки каждой из них.","privacy.ai.asis":"AI-gile это ранняя тестовая версия, предоставляемая как есть."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботы.","Делегировано."]},{"n":2,"texts":["Канбан роботов.","Агенты, организованные.","Идеи воплощены."]},{"n":3,"texts":["Канбан для роботов.","Идеи становятся функциями.","Бесплатный канбан агентов."]},{"n":5,"texts":["Канбан-доска, которой управляют агенты.","Ты пишешь карточки. Агенты строят.","Бесплатно, локально, проверено, чуть нелепо."]},{"n":8,"texts":["Бесплатная канбан-доска на твоём компьютере, где работают ИИ-агенты.","Напиши идею. Агенты построят. Ты примешь.","Agile для одного человека и многих терпеливых роботов."]},{"n":13,"texts":["Канбан-доска на твоём компьютере, где карточки берут в работу ИИ-агенты.","Напиши идею. Целая команда агентов её построит. Потом тестировщик всё проверит, и ты принимаешь.","Бесплатно, без аккаунтов и трекеров: доска, пара роботов и ты за главного."]},{"n":21,"texts":["AI-gile это канбан-доска для работы с ИИ-агентами, которые пишут код. Они берут карточки, а ты проверяешь и принимаешь результат.","У каждого проекта есть лид и команда ИИ-агентов. Оставь комментарий к любой карточке, и команда берётся за дело.","Бесплатный личный список дел, который работает на твоём компьютере. Работают роботы. А говорит «да» только один человек: ты."]},{"n":34,"texts":["Ты кладёшь идеи на доску. Команда ИИ-агентов превращает их в работающие функции, проверяет и возвращает тебе с шагами для пробы. Пока ты не скажешь «готово», ничто не считается готовым.","AI-gile это самодельная канбан-доска, которую Рич построил с огромной помощью агентов, которыми она теперь и управляет. Она бесплатна, работает на твоём компьютере и достаётся друзьям, а не продаётся.","Представь обычную канбан-доску с колонками от бэклога до «Готово», только карточки здесь берут ИИ-агенты. Они докладывают о ходе работы, задают вопросы, когда застряли, и всегда ждут твоего одобрения."]},{"n":55,"texts":["AI-gile это канбан-доска, где команда состоит из ИИ-агентов. У каждого проекта есть лид, который планирует работу, и помощники, которые её делают. Когда функция готова, ИИ-тестировщик пробует её и делает скриншот, а потом она попадает в твою стопку. Ты принимаешь её или оставляешь комментарий, и агенты переделывают.","Всё началось с того, что один человек пытался уследить сразу за множеством сеансов ИИ-программирования, и это выросло в настоящую доску. Она работает на твоём компьютере, не требует аккаунта и не ставит трекеры. Бесплатна для друзей и всех любопытных. Она ещё и недоделана, так что жди шероховатостей и сюрпризов.","Вот честная версия. Идеи по-прежнему придумываешь ты, и результат по-прежнему проверяешь ты. А AI-gile делает всё, что между ними: держит карточки в порядке, будит нужного агента, когда ты комментируешь, показывает, что именно изменилось, и собирает всё это в одну короткую стопку для тебя. Никакой магии, просто аккуратная работа, которую больше не нужно делать руками."]},{"n":89,"texts":["AI-gile это бесплатная канбан-доска, которая работает на твоём собственном компьютере. Вместо людей у каждого проекта команда ИИ-агентов: лид, который превращает твои идеи в карточки и план, и помощники, которые берут карточки по порядку важности. Когда что-то построено, ИИ-тестировщик проходит шаги проверки и показывает, что увидел. Потом результат ждёт в одной стопке под названием «Тебе». Ты принимаешь его или оставляешь комментарий, и команда пробует ещё раз. До «Готово» ничто не доходит без тебя.","Есть и неожиданные возможности. Ночной дозор пополняет колонку «К выполнению», пока ты спишь, и выбирает карточки, на которые не нужен твой ответ. Счётчик токенов показывает, сколько агенты израсходовали сегодня и за неделю, а режим без токенов велит им прекратить траты. Можно переписываться с друзьями, а личные сообщения защищены сквозным шифрованием. Доска говорит примерно на 120 языках, включая нидерландский, фламандский, пиратский и клингонский. Ничто из этого не стоит ни копейки, и никто не пытается тебе это продать.","AI-gile это небольшой личный проект, а не компания. Рич хотел присматривать за несколькими проектами с ИИ-программированием, не открывая каждое приложение, и вместе с агентами построил для этого доску, а затем с её помощью достроил всё остальное. Сейчас это закрытая пре-альфа: по большей части работает, но только у горстки друзей. Здесь нет страницы с ценами, рассылки и плана роста. Если звучит полезно, попроси попробовать, когда доступ чуть расширится. Сейчас она держится на терпении агентов и на отзывах друзей. Каждый отзыв превращается в карточку, а карточка рано или поздно превращается в готовую функцию."]},{"n":144,"texts":["AI-gile это канбан-доска для одного человека и множества ИИ-агентов. Она работает на твоём собственном компьютере и совершенно бесплатна. Ты добавляешь проекты, и у каждого проекта появляются лид и небольшая команда. Ты общаешься с лидом, как в Discord, и описываешь идею; лид превращает её в карточки и план, а потом ждёт, пока ты нажмёшь Go. Команда проходит по карточкам в порядке важности, пользуясь простой командной строкой, сделанной для языковых моделей. Прежде чем что-либо вернётся к тебе, ИИ-тестировщик проходит шаги в копии приложения и прикладывает скриншот. Готовая работа попадает в твою стопку вместе с изменёнными файлами и diff. Ты принимаешь её или оставляешь комментарий, и команда просыпается и пробует снова. Переместить карточку в «Готово» можешь только ты.","День с AI-gile выглядит примерно так. Вечером ты оставляешь несколько комментариев: эта кнопка не на месте, тот список надо отсортировать, а нельзя ли тёмную тему. И идёшь спать. Агенты читают комментарии, вносят правки, проверяют их и возвращают тебе. Если «К выполнению» пустеет, ночной дозор наполняет колонку из бэклога карточками, на которые не нужен твой ответ. Утром тебя ждёт одна короткая стопка: пара вопросов и несколько вещей на пробу, к каждой шаги, которые осилит сонный человек, и скриншот, где всё работает. Ты пролистываешь, принимаешь хорошее и возвращаешь остальное. Если что-то не понравилось, пишешь комментарий, и цикл начинается заново, без совещаний и без обид. Лид следит, чтобы работа шла по порядку, а скрам-мастер напоминает застрявшим карточкам, что они застряли. Счётчик токенов показывает расход, а режим без токенов выручает в скромные недели. Потом ты завтракаешь, а с этим агенты пока не помогут.","Сначала о том, чем AI-gile не является. Это не стартап, не товар на продажу, и никто не собирает твои данные. Это бесплатная доска, которая работает на твоём компьютере, без аккаунтов, трекеров и cookie. А вот что это такое: одно аккуратное место, где видны все проекты с ИИ-программированием сразу, где карточки делает команда агентов, а решения принимаешь ты. Она объединяет похожие карточки, исправляет запутанные названия и следит, чтобы код оставался лёгким. Она говорит примерно на 120 языках, от нидерландского и фламандского до пиратского и клингонского. Друзья могут переписываться друг с другом приватно и с шифрованием. Её построили Рич и множество терпеливых агентов, по большей части пользуясь ею же. Это закрытая пре-альфа, так что местами шероховато. Если звучит весело, попроси вежливо, и, возможно, попадёшь раньше других."]}],"quips":{"1":"Одно слово. Смело. Возможно, слишком смело.","3":"Три слова. Уже честнее большинства страниц о продуктах.","8":"Восемь слов. Всё ещё короче стендапа.","21":"Кстати, длины это story points. Конечно же.","55":"Пятьдесят пять слов. Пока ты читал, две карточки успели завершиться.","144":"Это самый длинный вариант. Варианта 233 нет. Агенты ушли спать."}},"timeline":{"first-idea.name":"Первая идея","first-idea.line":"Самый первый разговор, когда кода ещё не было.","first-board.name":"Первая доска","first-board.line":"Доска, которая следит за собственной разработкой: карточки, колонки, перетаскивание, проекты.","team-roles.name":"Команда и роли","team-roles.line":"Профили агентов, шаблоны команд, пространства и кто чем занят.","install.name":"Установка и релизы","install.line":"Архив, который друг сможет установить, самообновление, каналы и откат.","usage-saver.name":"Экономия расхода","usage-saver.line":"Измерять стоимость запусков, держать код лёгким, беречь лимит.","friends.name":"Друзья и общий доступ","friends.line":"Личные сообщения, зашифрованный ретранслятор, приглашения, роли и общие проекты.","languages.name":"Языки","languages.line":"Каждый текст на экране в языковом файле, сначала нидерландский и фламандский.","ai-tester.name":"ИИ-тестировщик","ai-tester.line":"Тестировщик первым проверяет каждую сдачу и показывает, что увидел.","website.name":"Сайт","website.line":"aigile.lol, тизер и эта хронология.","streaming.name":"Чат и стриминг","streaming.line":"Discord, Twitch, OBS, режим стримера, гифки и эмодзи.","no-ai.name":"Версия без ИИ","no-ai.line":"Доска для тех, кто пишет код без ИИ, и публичные доски.","night-watch.name":"Ночной дозор","night-watch.line":"Сторож и скрам-мастер держат команды в работе, пока ты спишь.","p-more.name":"Всё остальное","p-more.line":"Идеи поменьше, которые ждут своей очереди.","p-android.name":"Телефон и Android","p-android.line":"Доступ к доске с телефона, а потом и родное приложение для Android.","p-release.name":"Альфа и дальше","p-release.line":"Закрытая альфа, живой сайт, затем бета.","p-languages.name":"Ещё языки","p-languages.line":"130 языков и режим погружения для тех, кто учит язык.","p-engines.name":"Ещё ИИ-движки","p-engines.line":"Выбирай Claude, Codex, Gemini, Copilot или Cursor для каждого агента.","p-pro.name":"Профессиональная практика","p-pro.line":"Метки риска, барьеры слияния, карточки инцидентов и ограждения.","p-self.name":"Забота о тебе","p-self.line":"Режим усталости, напоминания о заботе о себе и 4:20.","p-servers.name":"Серверы и масштаб","p-servers.line":"Общие настройки сервера, роли и планы на рост.","p-livestream.name":"Дополнения для стриминга","p-livestream.line":"Чат Twitch, свои эмодзи и публичный просмотр вживую."},"words":{"button":"📖 Профессиональный жаргон","h":"📖 Словарик","intro":"Бесплатное обучение простым языком: каждое слово, которое тебе встретится, от первой идеи до услуги, на которую полагаются люди, а по пути Agile, разработка, безопасность и работа с ИИ.","search":"Найти слово…","none":"Такого слова нет.","close":"Закрыть","count":{"one":"{count} слово","other":"Слов: {count}"},"groups":[{"id":"idea","name":"💡 Идея и исследование"},{"id":"plan","name":"🗺️ Планирование работы"},{"id":"agile","name":"🔁 Гибкие способы работы"},{"id":"build","name":"🛠️ Как это строят"},{"id":"test","name":"🧪 Тестирование и качество"},{"id":"change","name":"🔀 Безопасные изменения"},{"id":"run","name":"🛎️ Как вести сервис"},{"id":"sec","name":"🔒 Безопасность и приватность"},{"id":"ai","name":"🤖 Работа с ИИ"},{"id":"money","name":"💰 Деньги и лицензии"}],"list":[{"id":"discovery","g":"idea","word":"Исследование (Discovery)","text":"Ранний этап, когда выясняют, какую проблему стоит решать и для кого, ещё до того, как что-то начали делать.","also":["фаза исследования","этап исследования","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Формулировка проблемы","text":"Одно-два предложения о том, у кого проблема, в чём она и почему важна, чтобы все целились в одно и то же.","also":["формулировку проблемы","формулировки проблемы","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Пользователь","text":"Человек, который пользуется тем, что ты создаёшь. Ради его потребностей и делается работа.","also":["пользователи","пользователя","пользователю","пользователем","пользователе","пользователей","пользователям","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Заинтересованная сторона","text":"Любой, кому небезразлично, чем закончится работа, или на кого она влияет: те, кто за неё платит, пользуется ею или её поддерживает.","also":["стейкхолдер","стейкхолдеры","заинтересованные стороны","заинтересованных сторон","стейкхолдера","стейкхолдеров","стейкхолдерам","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Персона","text":"Выдуманный, но реалистичный человек, который олицетворяет один тип пользователей, чтобы команда могла спросить: «Сэму это покажется простым?»","also":["персоны","персону","персоне","персоной","персон","persona","personas"]},{"id":"userresearch","g":"idea","word":"Исследование пользователей","text":"Разговоры с настоящими людьми и наблюдение за ними, чтобы узнать, что им нужно, а не гадать.","also":["интервью с пользователями","исследования пользователей","исследование пользователей","user research","user interviews"]},{"id":"journey","g":"idea","word":"Путь пользователя","text":"Шаги, которые человек проходит, чтобы чего-то добиться: от первого знакомства до результата, в том числе за пределами твоего продукта. Если нарисовать путь, видно, где человек застревает.","also":["пути пользователя","путь клиента","путь пользователя","путём пользователя","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Болевая точка","text":"То, что сегодня раздражает людей или тормозит их. Хорошие продукты убирают болевые точки.","also":["болевые точки","болевую точку","болевой точки","болевых точек","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Допущение","text":"То, во что веришь, но что ещё не проверено. Если записать допущения, будет видно, что проверять в первую очередь.","also":["допущения","предположение","допущению","допущений","предположения","предположений","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Гипотеза","text":"Лучшее предположение, которое ты собираешься проверить, вместе с тем, что ожидаешь увидеть, например: «люди зарегистрируются, если первый месяц бесплатный».","also":["гипотезы","гипотезу","гипотезе","гипотезой","гипотез","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Эксперимент","text":"Небольшая запланированная проверка, работает ли идея, прежде чем делать на неё большую ставку.","also":["эксперименты","эксперимента","эксперименту","экспериментом","эксперименте","экспериментов","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC, проверка концепции)","text":"Быстрая черновая попытка понять, может ли идея вообще сработать. Когда ответ получен, её обычно выбрасывают.","also":["проверка концепции","пруф оф концепт","проверки концепции","проверку концепции","PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Прототип","text":"Ранняя модель продукта, часто это просто картинки, по которым можно щёлкать, чтобы проверить идею на людях до того, как делать всё как следует.","also":["прототипы","прототипа","прототипу","прототипом","прототипе","прототипов","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Вайрфрейм","text":"Простой набросок экрана, показывающий, что где стоит, без цветов и настоящего содержимого.","also":["вайрфреймы","схема экрана","вайрфрейма","вайрфреймов","схемы экрана","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Макет","text":"Подробная картинка того, как будет выглядеть экран, с настоящими цветами и текстом, но пока ничего не работает.","also":["макеты","мокап","макета","макету","макетом","макете","макетов","мокапы","мокапа","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Бизнес-кейс","text":"Доводы в пользу проекта: сколько он стоит, что приносит или экономит и какие в нём риски.","also":["бизнес-обоснование","бизнес-кейса","бизнес-кейсы","бизнес-обоснования","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Осуществимость","text":"Можно ли это на самом деле сделать и поддерживать при тех времени, деньгах и умениях, которые у тебя есть.","also":["выполнимость","осуществимости","выполнимости","feasibility"]},{"id":"outcome","g":"idea","word":"Результат для людей (Outcome)","text":"Перемена к лучшему для людей, которой ты хочешь добиться, например меньше пропущенных визитов. Она важнее, чем объём сделанного.","also":["эффект","эффекта","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Выпуск (Output)","text":"То, что делает команда, например новый экран или отчёт. Само по себе то, что это сделано, ещё не значит, что кому-то стало лучше.","also":["выход","выхода","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Метрика успеха","text":"Число, которое показывает, сделала ли работа то, ради чего её затевали, например: больше людей доводят заказ до конца.","also":["метрики успеха","метрику успеха","метрикой успеха","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Ключевой показатель эффективности (KPI)","text":"Важное число, за которым следишь, чтобы понимать, всё ли идёт хорошо, например число регистраций в неделю.","also":["КПЭ","ключевые показатели","ключевых показателей","ключевого показателя","KPI","key performance indicator","KPIs"]},{"id":"okr","g":"idea","word":"Цели и ключевые результаты (OKR)","text":"Способ ставить цели: цель говорит, чего ты хочешь, а несколько ключевых результатов — это числа, которые показывают, что цель достигнута.","also":["ОКР","OKR","OKRs"]},{"id":"product","g":"plan","word":"Продукт","text":"То, что создают и поддерживают для пользователей: приложение, сайт или инструмент.","also":["продукты","продукта","продукту","продуктом","продукте","продуктов","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Видение продукта","text":"Короткое заявление о том, кому помогает продукт и куда он движется в долгосрочной перспективе.","also":["продуктовое видение","видения продукта","видением продукта","vision statement","product vision"]},{"id":"po","g":"plan","word":"Владелец продукта (PO)","text":"Человек, который решает, что делать и в каком порядке, чтобы команда всегда занималась самым важным. В AI-gile это ты.","also":["продакт оунер","владельца продукта","владельцу продукта","владельцем продукта","продакт-оунер","PO","product owner","product owners"]},{"id":"pm","g":"plan","word":"Менеджер продукта (PM)","text":"Человек, который отвечает за направление продукта: какие проблемы он решает, для кого и зачем. PM может означать и менеджера проекта, так что уточняй, о ком речь.","also":["продакт-менеджер","менеджера продукта","менеджеру продукта","продакт-менеджера","продакт-менеджеры","PM","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Менеджер проекта","text":"Человек, который следит, чтобы проект укладывался в сроки и бюджет, и отслеживает, кто что делает и к какому времени.","also":["проджект-менеджер","руководитель проекта","менеджера проекта","менеджеру проекта","руководителя проекта","проджект-менеджера","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Дорожная карта","text":"Примерный план того, что будет в ближайшие месяцы, по порядку. Она показывает направление, а не точные даты, и меняется по мере того, как ты узнаёшь новое.","also":["роадмап","дорожную карту","дорожной карты","дорожной карте","роадмапа","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Веха","text":"Точка в проекте, которую стоит отметить, например «первая версия запущена» или «100 пользователей».","also":["вехи","веху","вехе","вехой","вех","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Минимально жизнеспособный продукт (MVP)","text":"Самая маленькая версия продукта, которая всё же полезна настоящим людям, чтобы учиться у них как можно раньше.","also":["МВП","минимально жизнеспособного продукта","MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Требование","text":"То, что готовый продукт должен делать или чем должен быть.","also":["требования","требованию","требованием","требований","требованиям","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Объём работ (Scope)","text":"Что входит в работу и, не менее важно, что в неё не входит.","also":["рамки проекта","объёма работ","объём работ","рамок проекта","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Расползание объёма (Scope creep)","text":"Когда в работу понемногу добавляется всё больше и больше, а о лишнем времени и деньгах никто не договаривался, и поэтому она никак не заканчивается.","also":["расползание требований","расползания объёма","расползание объёма","расползания требований","scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Функция","text":"Одна вещь, которую продукт умеет делать для людей, например «сбросить пароль».","also":["функции","фича","фичи","функцию","функцией","функций","фичу","фич","фичей","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Эпик","text":"Крупный кусок работы, слишком большой, чтобы сделать его за один раз, поэтому его делят на карточки поменьше.","also":["эпики","эпика","эпику","эпиком","эпике","эпиков","epic","epics"]},{"id":"story","g":"plan","word":"Пользовательская история","text":"Небольшая работа, описанная со стороны пользователя: «Как покупатель, я хочу сохранить корзину, чтобы закончить позже». С неё начинается разговор о том, что делать.","also":["юзер-стори","пользовательской истории","пользовательские истории","пользовательских историй","user story","user stories"]},{"id":"ac","g":"plan","word":"Критерии приёмки (AC)","text":"Проверки, которые карточка должна пройти, чтобы считаться готовой; их согласовывают до начала работы, например: «корзина на месте после выхода и повторного входа».","also":["критериев приёмки","критериям приёмки","критериях приёмки","AC","acceptance criteria"]},{"id":"task","g":"plan","word":"Задача","text":"Одно дело, которое нужно сделать, часто это небольшой шаг большой истории.","also":["задачи","задачу","задаче","задачей","задач","задачам","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Тикет","text":"Ещё одно слово для карточки: одна работа или одна просьба, за которой следят от начала до конца.","also":["тикеты","тикета","тикету","тикетом","тикете","тикетов","ticket","tickets"]},{"id":"priority","g":"plan","word":"Приоритет","text":"Насколько что-то важно или срочно по сравнению со всем остальным, чтобы самое важное делалось первым.","also":["приоритеты","приоритета","приоритету","приоритетом","приоритете","приоритетов","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Расстановка приоритетов","text":"Выстраивание работы по важности. Один из известных способов — MoSCoW: Must have (обязательно), Should have (желательно), Could have (можно), Won’t have (не в этот раз).","also":["приоритизация","расстановки приоритетов","приоритизации","приоритизацию","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Оценка","text":"Прикидка того, насколько велика работа или сколько времени она займёт. Это прикидка, а не обещание.","also":["оценки","оценивание","оценку","оценке","оценкой","оценок","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points (баллы истории)","text":"Способ прикинуть размер работы, сравнивая карточки друг с другом («примерно вдвое больше той»), а не в часах. Сравнивать по ним команды нельзя.","also":["стори-пойнты","сторипоинты","стори-пойнтов","сторипоинтов","баллы истории","баллов истории","story point","story points"]},{"id":"tshirt","g":"plan","word":"Оценка в размерах футболок","text":"Оценка размера работы как S, M, L или XL. Быстро и достаточно хорошо для раннего планирования.","also":["размеры футболок","размерах футболок","T-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Покер планирования","text":"Игра для оценки: все одновременно показывают карту с размером, а потом те, кто назвал самый большой и самый маленький, объясняют почему.","also":["скрам-покер","покера планирования","покер планирования","скрам-покера","Planning poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"Зависимость","text":"Когда одна работа не может начаться или закончиться, пока не сделана другая.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Блокер","text":"Всё, что прямо сейчас мешает работе двигаться вперёд, например отсутствующий ответ или сломанный инструмент.","also":["блокеры","блокера","блокеру","блокером","блокеров","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Дедлайн","text":"Дата, к которой что-то должно быть закончено.","also":["дедлайны","крайний срок","дедлайна","дедлайну","дедлайном","дедлайнов","крайнего срока","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Результат работы (Deliverable)","text":"Нечто конкретное, что работа создаёт и передаёт, например работающая страница или отчёт.","also":["поставляемый результат","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Прогноз","text":"Предсказание того, что скорее всего произойдёт, например когда работа будет готова, на основе того, что известно на сегодня.","also":["прогнозы","прогноза","прогнозу","прогнозом","прогнозов","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Метрика","text":"Всё, что ты измеряешь и отслеживаешь со временем, например число посещений страницы или сколько времени занимает исправление.","also":["метрики","метрику","метрике","метрикой","метрик","metric","metrics"]},{"id":"feedback","g":"plan","word":"Обратная связь","text":"Что люди говорят о твоей работе, хорошее и плохое. Получать её рано и часто — сама суть Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Бэклог","text":"Очередь идей и работы, которые ещё не запланированы; самое важное — сверху. Пока что-то не перейдёт в «К выполнению», над этим никто не работает."},{"id":"sprint","g":"agile","word":"Спринт","text":"Короткий, чётко ограниченный отрезок работы (часто одна-две недели, но не больше месяца) с целью и согласованным набором карточек, которые нужно закончить.","also":["спринта","спринту","спринте","спринты","спринтов","спринтом"]},{"id":"standup","g":"agile","word":"Стендап","text":"Короткая ежедневная сверка: что сделал каждый участник команды, что будет делать дальше и что ему мешает. В Scrum её называют ежедневным скрамом.","also":["стендапы","стендапа","стендапу","ежедневный скрам","стендапе","стендапов","стендапом","standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Канбан","text":"Способ работы, при котором карточки движутся по колонкам доски (например, К выполнению, В работе, Готово), а команда ограничивает, сколько в работе одновременно, чтобы работа не стояла."},{"id":"wip","g":"agile","word":"WIP-лимит","text":"WIP — сокращение от work in progress (работа в процессе). WIP-лимит — наибольшее число карточек, которое может быть в колонке одновременно, чтобы команда заканчивала дела, прежде чем начинать новые.","also":["WIP"]},{"id":"dod","g":"agile","word":"Критерии «Сделано»","text":"Короткий чек-лист команды о том, что значит «готово», например проверено и объяснено, прежде чем карточка попадёт к тебе. Его близнец, критерии «Готово к работе», говорит, когда карточка достаточно понятна, чтобы начать.","also":["критерии готовности к работе","определение готовности","критериев готовности","Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Ретро","text":"Регулярный взгляд назад на то, как работает команда, чтобы договориться об одной-двух вещах, которые в следующий раз сделать лучше. Сокращение от «ретроспектива». В AI-gile ретро предлагает изменение в правилах работы команды, а ты отвечаешь «Давай» или «Пока нет».","also":["ретроспектива","ретроспективы"]},{"id":"swarm","g":"agile","word":"Рой","text":"Все на палубу: много людей бросают другую работу и вместе чинят одно срочное дело, пока оно не решено. В AI-gile каждая команда помогает одному проекту, а остальные проекты в это время ждут.","also":["режим роя","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"В Scrum — человек, который помогает команде хорошо работать: убирает то, что ей мешает, держит встречи в русле и учит хорошим привычкам, никем не командуя. В AI-gile Lead Scrum Master замечает застрявшие карточки, подталкивает команды и напоминает тебе, что ждёт, во всех проектах.","also":["скрам-мастер","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (гибкая разработка)","text":"Способ работать небольшими шагами: сделай немного, часто показывай настоящие результаты, учись на том, что говорят люди, и меняй план по ходу дела, а не планируй всё заранее.","also":["аджайл","гибкие методологии","аджайла","аджайлу","гибкой разработки","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Манифест Agile","text":"Короткое заявление, написанное в 2001 году людьми, которые делают программы. В нём люди, работающий результат, тесная работа с заказчиками и готовность к переменам стоят выше тяжёлых планов и бумаг.","also":["гибкий манифест","манифеста Agile","манифест Agile","Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Водопад (Waterfall)","text":"Старый способ работы: сначала спланировать всё, потом всё построить, потом всё проверить, этап за этапом. Менять что-то поздно трудно и дорого.","also":["водопадная модель","водопадной модели","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Итерация","text":"Один круг: сделать что-то, проверить и улучшить. Работа по Agile — это цепочка таких кругов, а спринт — один из их видов.","also":["итерации","итерацию","итерацией","итераций","iteration","iterations"]},{"id":"increment","g":"agile","word":"Инкремент","text":"Новый работающий кусок продукта, добавленный за спринт или круг работы и совместимый с тем, что уже было.","also":["инкременты","инкремента","инкременту","инкрементом","инкрементов","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum (Скрам)","text":"Популярный способ работать по Agile: небольшая команда работает короткими спринтами к цели, у неё есть заранее определённые роли и несколько регулярных встреч, чтобы планировать, проверять и улучшать."},{"id":"scrumteam","g":"agile","word":"Scrum-команда","text":"Небольшая группа, которая делает работу в Scrum: владелец продукта, Scrum-мастер и разработчики.","also":["скрам-команда","Scrum-команды","Scrum-команду","скрам-команды","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"События Scrum","text":"Регулярные встречи в Scrum: планирование спринта, ежедневный скрам, обзор спринта и ретро. Многие называют их церемониями.","also":["церемонии","церемонии Scrum","событий Scrum","события Scrum","церемоний","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Планирование спринта","text":"Встреча в начале спринта, на которой команда договаривается, зачем нужен этот спринт, какие карточки брать и с чего начать.","also":["встреча по планированию","планирования спринта","планировании спринта","планирование спринта","Sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Цель спринта","text":"Одно предложение о том, ради чего этот спринт. Мелкие задачи по ходу дела могут меняться, лишь бы цель была достигнута.","also":["цели спринта","цель спринта","целью спринта","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Бэклог спринта","text":"Карточки, выбранные для текущего спринта, вместе с планом команды, как их сделать.","also":["бэклоги спринта","бэклога спринта","бэклоге спринта","бэклог спринта","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Бэклог продукта","text":"Полный упорядоченный список всего, что можно сделать для продукта, самое важное сверху. Он постоянно меняется по мере того, как ты узнаёшь новое.","also":["продуктовый бэклог","бэклога продукта","бэклоге продукта","бэклог продукта","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Цель продукта","text":"Более крупный результат, к которому движется продукт; он помогает команде выбирать, что делать дальше.","also":["цели продукта","цель продукта","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Уточнение бэклога","text":"Регулярный просмотр бэклога: навести порядок, разбить, упорядочить и дополнить карточки деталями, чтобы их можно было брать в работу. Ещё это называют грумингом бэклога.","also":["груминг бэклога","груминг","уточнения бэклога","уточнение бэклога","груминга","backlog grooming","refinement","backlog refinement"]},{"id":"sprintreview","g":"agile","word":"Обзор спринта","text":"Встреча в конце спринта, на которой команда показывает, что успела сделать, и слушает, что думают люди, чтобы решить, что дальше.","also":["ревью спринта","обзора спринта","обзоре спринта","обзор спринта","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Демо","text":"Показ готовой работы вживую, в действии, тем, кто о ней просил.","also":["демонстрация","демонстрации","демонстрацию","демку","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Таймбокс","text":"Фиксированное количество времени на что-то. Когда оно заканчивается, ты останавливаешься, даже если сделано не всё.","also":["таймбокса","таймбоксы","таймбоксом","timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Скорость команды (Velocity)","text":"Сколько работы команда обычно успевает закончить за спринт; по этому числу планируют, сколько брать в следующий раз. Это не оценка того, насколько усердно люди работают.","also":["велосити","скорости команды","скорость команды","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Ёмкость команды (Capacity)","text":"Сколько работы команда может взять на себя за период, с учётом отпусков и других дел.","noTip":1},{"id":"burndown","g":"agile","word":"Диаграмма сгорания (Burndown)","text":"График оставшейся в спринте работы, который день за днём идёт вниз. Если линия не опускается, что-то застряло.","also":["бёрндаун","диаграммы сгорания","диаграмму сгорания","диаграмма сгорания","burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Диаграмма накопления (Burnup)","text":"График готовой работы, растущей со временем, рядом с общим планом, чтобы видеть, когда ты дойдёшь до цели.","also":["бёрнап","диаграммы накопления","диаграмму накопления","диаграмма накопления","burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Канбан-доска","text":"Сама доска: колонка для каждого этапа работы, а карточки движутся слева направо.","also":["доска Kanban","канбан-доски","канбан-доску","канбан-доске","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Система вытягивания (Pull)","text":"Способ работы, при котором новая работа начинается, только когда у кого-то появилось место её взять, а не навешивается на того, у кого и так всё занято.","also":["pull-система","системы вытягивания","система вытягивания","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Поток","text":"Насколько гладко работа движется по доске. Хороший поток — это когда карточки идут дальше, а не копятся.","also":["поток работы","потока","потоку","потоком","потоке","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Время выполнения (Lead time)","text":"Сколько проходит времени от того, как кто-то попросил о чём-то, до того, как это сделано.","also":["лид-тайм","lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Время цикла (Cycle time)","text":"Сколько времени занимает карточка с того момента, когда работа над ней действительно началась, до того, как она готова.","also":["цикл-тайм","времени цикла","время цикла","cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Пропускная способность (Throughput)","text":"Сколько карточек заканчивается за неделю или за любой другой отрезок времени.","also":["пропускной способности","пропускная способность","throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Узкое место","text":"Тот этап, где работа копится и тормозит всё, что идёт за ним, как узкое горлышко бутылки.","also":["бутылочное горлышко","узкого места","узкие места","узких мест","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Дорожка (Swimlane)","text":"Строка поперёк доски, где собраны карточки одного вида, например срочные или карточки одной команды.","also":["свимлейн","свимлейны","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (бережливость)","text":"Способ работать, при котором убирают потери (всё, что не помогает клиенту) и поддерживают поток работы."},{"id":"waste","g":"agile","word":"Потери","text":"В Lean — всё, что требует усилий, но не помогает клиенту: ожидание, переделки или создание того, чем никто не пользуется.","noTip":1},{"id":"kaizen","g":"agile","word":"Непрерывное улучшение","text":"Понемногу становиться лучше за счёт небольших регулярных изменений, а потом проверять, помогли ли они. Ретро — один из способов. Ещё это называют кайдзен.","also":["кайдзен","непрерывного улучшения","непрерывное улучшение","kaizen"]},{"id":"selforg","g":"agile","word":"Самоорганизующаяся команда","text":"Команда, которая сама решает, как делать работу, а не получает указания шаг за шагом.","also":["самоорганизация","самоорганизующейся команды","самоорганизующиеся команды","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Кросс-функциональная команда","text":"Команда, у которой есть все умения, чтобы довести работу до конца самой: дизайн, разработка и тестирование.","also":["кроссфункциональная команда","кросс-функциональной команды","кросс-функциональные команды","cross-functional"]},{"id":"spike","g":"agile","word":"Спайк (Spike)","text":"Короткое исследование с ограничением по времени, чтобы ответить на вопрос, прежде чем браться за настоящую работу.","also":["исследовательская задача","спайк","спайка","спайки","спайков","spike","spikes"]},{"id":"rework","g":"agile","word":"Переделка","text":"Когда работу делают заново, потому что с первого раза получилось не так.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Масштабируемый Agile (SAFe)","text":"Способы применять Agile во многих командах крупной организации. SAFe (Scaled Agile Framework) — один из самых известных примеров.","also":["масштабирование Agile","масштабируемого Agile","scaled Agile"]},{"id":"repo","g":"build","word":"Репозиторий","text":"Папка проекта с кодом и полной историей коммитов. Она может лежать на твоём компьютере, на GitHub или и там и там.","also":["репо","репозитория","репозитории"]},{"id":"branch","g":"build","word":"Ветка","text":"Отдельная линия работы в коде, чтобы вносить изменения, не трогая основную версию.","also":["ветки","ветку","ветке","веток","веткой"]},{"id":"commit","g":"build","word":"Коммит","text":"Сохранённый снимок кода с короткой заметкой о том, что изменилось. К любому из них всегда можно вернуться.","also":["коммиты","коммита","коммитов","коммиту","коммите"]},{"id":"push","g":"build","word":"Пуш","text":"Отправка твоих сохранённых снимков (коммитов) с этого компьютера в общую копию онлайн, например на GitHub, чтобы они были в резерве и другие могли их получить."},{"id":"merge","g":"build","word":"Мерж","text":"Слияние изменений одной ветки в другую, обычно обратно в основную версию."},{"id":"pr","g":"build","word":"Пулл-реквест","text":"Просьба проверить изменения ветки и влить их в основную версию. На некоторых сайтах это называют merge request.","also":["пулл-реквесты","мерж-реквест","пулл-реквеста","пулл-реквест","PR-а","PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Рефакторинг","text":"Наведение порядка в коде без изменения того, что он делает: файлы меньше, названия понятнее, повторов меньше."},{"id":"bug","g":"build","word":"Баг","text":"Что-то, что работает не так, как должно.","also":["баги","бага","багов","багу","багом","ошибка"]},{"id":"peerreview","g":"build","word":"Взаимная проверка","text":"Вторая пара глаз: кто-то другой, не автор, проверяет работу, прежде чем она дойдёт до тебя, так что ошибок проскакивает меньше. В AI-gile каждую карточку проверяет другой ИИ.","also":["ревью","код-ревью","code review","peer review"]},{"id":"code","g":"build","word":"Код","text":"Записанные инструкции, которые говорят компьютеру, что делать. Ещё это называют исходным кодом.","also":["исходный код","кода","коду","кодом","коде","исходного кода","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Язык программирования","text":"Язык, на котором пишут код, например JavaScript, Python или Java. Для разных задач подходят разные.","also":["языки программирования","языка программирования","языке программирования","языков программирования","programming language","programming languages"]},{"id":"developer","g":"build","word":"Разработчик (dev)","text":"Человек, который пишет и меняет код. Его ещё называют программистом или инженером-программистом.","also":["разработчики","программист","программисты","разработчика","разработчику","разработчиком","разработчиков","программиста","программистов","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Программное обеспечение (ПО)","text":"Программы, которые работают на компьютерах и телефонах, в отличие от самих устройств (железа).","noTip":1},{"id":"app","g":"build","word":"Приложение","text":"Программа, которой люди пользуются, чтобы что-то сделать, на телефоне, компьютере или в браузере.","also":["приложения","апп","приложение","приложению","приложением","приложении","приложений","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Веб-приложение","text":"Приложение, которое работает в браузере, поэтому ничего устанавливать не нужно.","also":["веб-приложения","веб-приложение","веб-приложений","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Фронтенд","text":"Часть приложения, которую ты видишь и на которую нажимаешь: экраны, кнопки и слова, часто прямо в браузере.","also":["клиентская часть","фронтенд","фронтенда","фронтенде","front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Бэкенд","text":"Закулисная часть приложения, которая хранит данные и делает работу, когда ты на что-то нажимаешь, например проверяет пароль.","also":["серверная часть","бэкенд","бэкенда","бэкенде","back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Фулстек","text":"Работа и над фронтендом, и над бэкендом.","also":["фулстэк","фулстек","фулстека","full stack","full-stack"]},{"id":"ui","g":"build","word":"Пользовательский интерфейс (UI)","text":"То, что человек видит и использует на экране: расположение, кнопки, меню и текст.","also":["пользовательского интерфейса","UI","user interface"]},{"id":"ux","g":"build","word":"Пользовательский опыт (UX)","text":"Каково пользоваться чем-то: легко, понятно и приятно или запутанно и медленно.","also":["юзабилити","пользовательского опыта","пользовательский опыт","UX","user experience"]},{"id":"accessibility","g":"build","word":"Доступность (a11y)","text":"Делать так, чтобы продуктом могли пользоваться все, в том числе те, кто плохо видит, не может пользоваться мышью или пользуется программой чтения с экрана.","also":["универсальный доступ","a11y","accessibility"]},{"id":"responsive","g":"build","word":"Адаптивный дизайн","text":"Делать страницы так, чтобы они хорошо выглядели и работали на любом экране, от телефона до большого монитора.","also":["адаптивная вёрстка","адаптивного дизайна","адаптивный дизайн","responsive design"]},{"id":"designsys","g":"build","word":"Дизайн-система","text":"Общий набор цветов, шрифтов, кнопок и правил, чтобы каждый экран выглядел и вёл себя одинаково.","also":["дизайн-системы","дизайн-систему","дизайн-системе","дизайн-систем","design system","design systems"]},{"id":"architecture","g":"build","word":"Архитектура","text":"Общее устройство системы: из каких главных частей она состоит и как они общаются друг с другом."},{"id":"database","g":"build","word":"База данных (БД)","text":"Упорядоченное хранилище информации, как очень мощная таблица, которую приложение может читать и менять.","also":["БД","базы данных","базу данных","базе данных","баз данных","database","databases","DB"]},{"id":"schema","g":"build","word":"Схема базы данных","text":"Устройство базы данных: какие в ней есть таблицы с информацией и что лежит в каждой.","also":["схему базы данных","схемы базы данных","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Сокращение от «язык структурированных запросов»: язык, на котором у большинства баз данных запрашивают информацию или меняют её.","also":["язык запросов","SQL-запрос","SQL-запросы","Structured Query Language"]},{"id":"data","g":"build","word":"Данные","text":"Информация, которую хранит компьютер, например имена, заказы или настройки.","also":["набор данных","датасет","данных","данным","данными","dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Сервер","text":"Компьютер, который всегда включён и отвечает на запросы других компьютеров, например отдаёт тебе веб-страницу, когда ты её открываешь.","also":["серверы","сервера","серверу","сервером","сервере","серверов","server","servers"]},{"id":"client","g":"build","word":"Клиент","text":"Сторона, которая что-то просит у сервера, обычно твой браузер или приложение. В бизнесе так ещё называют просто покупателя.","also":["клиенты","клиента","клиенту","клиентом","клиенте","клиентов","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Сокращение от «программный интерфейс приложения»: готовое меню запросов, с которыми одна программа может обратиться к другой, например спросить у службы погоды прогноз на сегодня.","also":["АПИ","интерфейс программирования","APIs","application programming interface","API"]},{"id":"endpoint","g":"build","word":"Эндпоинт","text":"Один пункт в меню API: веб-адрес, к которому программа может обратиться, чтобы что-то получить или отправить.","also":["точка доступа","эндпоинта","эндпоинты","эндпоинтов","endpoint","endpoints"]},{"id":"integration","g":"build","word":"Интеграция","text":"Соединение двух систем, чтобы они работали вместе, например когда твой магазин сам отправляет заказы в бухгалтерскую программу.","also":["интеграции","интеграцию","интеграцией","интеграций","integration","integrations"]},{"id":"webhook","g":"build","word":"Вебхук","text":"Сообщение, которое одна система сама отправляет другой в тот момент, когда что-то случилось, например «платёж получен».","also":["вебхуки","вебхука","вебхуков","вебхуком","webhook","webhooks"]},{"id":"library","g":"build","word":"Библиотека","text":"Готовый код, который написал кто-то другой и который можно использовать повторно, а не писать самому.","also":["библиотеки","библиотеку","библиотеке","библиотекой","библиотек","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Фреймворк","text":"Готовый каркас для создания приложения, который во многом определяет, как устроен код, как каркас дома, который ты заполняешь.","also":["фреймворки","фреймворка","фреймворком","фреймворков","framework","frameworks"]},{"id":"sdk","g":"build","word":"Набор для разработки (SDK)","text":"Набор инструментов, кода и примеров для создания программ под одну платформу или службу.","also":["СДК","SDK","SDKs"]},{"id":"softdep","g":"build","word":"Программная зависимость","text":"Библиотека или инструмент, без которых твой код не работает. Держать их обновлёнными важно для безопасности.","also":["зависимости кода","программной зависимости","программные зависимости","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Пакет","text":"Набор готового кода, который можно установить и использовать в проекте.","also":["пакеты","пакета","пакету","пакетом","пакете","пакетов","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Менеджер пакетов","text":"Инструмент, который скачивает и обновляет пакеты, от которых зависит твой код. npm — один из самых распространённых.","also":["менеджеры пакетов","менеджера пакетов","менеджером пакетов","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Самый распространённый инструмент для хранения истории изменений кода в виде коммитов и веток."},{"id":"github","g":"build","word":"GitHub","text":"Сайт, на котором хранятся репозитории Git, чтобы команды могли делиться кодом, проверять изменения и следить за работой."},{"id":"vcs","g":"build","word":"Система контроля версий","text":"Хранение полной истории каждого изменения файлов, чтобы видеть, кто что поменял, и при необходимости вернуться назад. Git делает именно это.","also":["контроль версий","системы контроля версий","контроля версий","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Клонирование","text":"Создание собственной полной копии репозитория вместе с историей на твоём компьютере.","also":["клонировать","клонирования","клон","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (получить изменения)","text":"Загрузка на твой компьютер последних коммитов из общей копии (например, с GitHub). Противоположность push.","also":["пулл","пулла","сделать pull","git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Основная ветка","text":"Официальная версия кода, от которой все работают; её часто называют main или master.","also":["главная ветка","основной ветки","основную ветку","основной ветке","main","master","main branch","master branch"]},{"id":"conflict","g":"build","word":"Конфликт слияния","text":"Когда два изменения по-разному затрагивают одни и те же строки, компьютер не может их соединить, и выбирать приходится человеку.","also":["мерж-конфликт","конфликта слияния","конфликты слияния","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (разница)","text":"Вид, который показывает, что именно изменилось между двумя версиями: какие строки добавлены, а какие убраны.","also":["дифф","диффа","диффы","diff","diffs"]},{"id":"fork","g":"build","word":"Форк","text":"Твоя собственная копия чужого репозитория, которую можно менять, не затрагивая оригинал.","also":["форки","форка","форку","форком","форков","форкнуть","fork","forks","forked"]},{"id":"script","g":"build","word":"Скрипт","text":"Короткая программа, которая сама делает одно дело, например наводит порядок в файлах или запускает приложение.","also":["скрипты","скрипта","скрипту","скриптом","скрипте","скриптов","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Сборка","text":"Превращение кода во что-то готовое к запуску, а также сам готовый к запуску результат.","also":["билд","сборки","сборку","сборкой","сборок","билда","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Компиляция","text":"Перевод кода, который написали люди, в вид, который компьютер может выполнять напрямую.","also":["компилировать","компилятор","компиляции","компилятора","compile","compiler"]},{"id":"cli","g":"build","word":"Командная строка (CLI)","text":"Текстовое окно, в котором ты печатаешь компьютеру команды, а не нажимаешь кнопки мышью. Ещё это называют терминалом.","also":["терминал","консоль","командной строки","командной строке","терминала","консоли","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Конфигурация (конфиг)","text":"Настройки, которые управляют поведением программы; их хранят отдельно от кода, чтобы их легко было менять.","also":["конфиг","настройки","конфига","конфигурации","конфигом","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Переменная окружения","text":"Настройка, которую передают программе при запуске; в ней часто хранят адреса или пароли, чтобы не писать их прямо в коде.","also":["переменные окружения","переменной окружения","переменных окружения","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Отладка","text":"Поиск причины, почему что-то не работает, и её исправление.","also":["дебаг","отлаживать","отладки","отладку","дебага","debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Парное программирование","text":"Двое (или человек и ИИ) работают над одним кодом вместе: один печатает, другой проверяет.","also":["пейринг","парного программирования","pair programming","pairing"]},{"id":"docs","g":"build","word":"Документация","text":"Письменные пояснения о том, как что-то устроено и как этим пользоваться.","also":["доки","документы","документации","документацию","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README (Ридми)","text":"Первый файл, который стоит прочитать в репозитории: что это за проект и как его запустить.","also":["ридми","READMEs","README"]},{"id":"legacy","g":"build","word":"Унаследованная система (Legacy)","text":"Старая система, которая всё ещё используется и которую трудно менять, часто потому, что её понимает уже мало кто.","also":["легаси","унаследованный код","унаследованной системы","легаси-код","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Технический долг","text":"Упрощения на скорую руку, которые сейчас экономят время, но замедляют будущие изменения, как кредит, на который набегают проценты. Рефакторинг гасит этот долг.","also":["техдолг","технического долга","техдолга","техническим долгом","technical debt","tech debt"]},{"id":"test","g":"test","word":"Тест","text":"Проверка, что что-то работает как надо. Одни тесты компьютер запускает сам при каждом изменении кода, другие — это ты, когда пробуешь готовую карточку, прежде чем принять её.","also":["тесты","теста","тесту","тестов","тестом","тестировать","тестирование","протестируешь","тесте"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Сокращение от quality assurance, то есть контроль качества: всё, что делается, чтобы работа была правильной до выхода в прод. В AI-gile это автоматические проверки: если QA красный, что-то не прошло, и выпускать нельзя, пока это не исправят.","also":["контроль качества","проверки качества"]},{"id":"testpile","g":"test","word":"Стопка тестов","text":"Готовые карточки, которые ждут, когда ты их попробуешь, одна за другой. Прими карточку или верни её с заметкой, и появится следующая.","also":["стопки тестов","test pile"]},{"id":"autotest","g":"test","word":"Автоматический тест","text":"Проверка, которую компьютер запускает сам при каждом изменении кода, чтобы рано поймать ошибки.","also":["автотест","автотесты","автоматические тесты","автотеста","автотестов","автотестами","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ручной тест","text":"Человек сам, вручную, пробует работу, чтобы увидеть, ведёт ли она себя так, как надо.","also":["ручное тестирование","ручного теста","ручные тесты","ручного тестирования","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Модульный тест (unit-тест)","text":"Маленькая автоматическая проверка одного крошечного кусочка кода отдельно от остального.","also":["юнит-тест","юнит-тесты","модульного теста","модульные тесты","модульных тестов","юнит-тестов","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Интеграционный тест","text":"Проверка того, что несколько частей правильно работают вместе, а не только по одной.","also":["интеграционные тесты","интеграционного теста","интеграционных тестов","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Сквозной тест (E2E)","text":"Тест, который действует как настоящий пользователь от начала до конца, например регистрируется, покупает и платит.","also":["сквозное тестирование","сквозного теста","сквозные тесты","сквозных тестов","E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Приёмочное тестирование (UAT)","text":"Те, кто просил о работе, сами пробуют её и говорят, делает ли она то, что им нужно. Стопка тестов в AI-gile — это его вариант такой проверки.","also":["приёмка","приёмочного тестирования","приёмку","UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Регрессия","text":"Что-то, что раньше работало, но сломалось после изменения. Регрессионные тесты проверяют, что старое по-прежнему работает.","also":["регрессии","регрессионный тест","регрессионное тестирование","регрессию","регрессией","регрессий","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Дымовой тест (smoke test)","text":"Очень быстрая проверка, что главное вообще работает, например сразу после выхода изменения. Если она не проходит, остановись и разберись.","also":["смоук-тест","дымовое тестирование","дымового теста","дымовые тесты","смоук-тесты","smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Исследовательское тестирование","text":"Свободно пробовать продукт и тыкать в него по-разному, чтобы найти проблемы, которые пропустят заранее запланированные проверки.","also":["эксплораторное тестирование","исследовательского тестирования","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Тест-кейс","text":"Один записанный сценарий для проверки: шаги и то, что должно получиться.","also":["тест-кейсы","тестовый сценарий","тест-кейса","тест-кейсов","test case","test cases"]},{"id":"coverage","g":"test","word":"Покрытие тестами","text":"Какая часть кода проверяется автоматическими тестами. Обычно чем больше, тем надёжнее, но высокое покрытие само по себе не доказывает, что всё работает хорошо.","also":["покрытие кода","покрытия тестами","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Тестовые данные","text":"Выдуманная информация для примера, которую используют при тестировании, чтобы не раскрывать личные данные настоящих людей.","also":["фикстуры","тестовых данных","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Крайний случай","text":"Необычная ситуация на границе возможного, например пустая форма или имя с апострофом, где всё часто ломается.","also":["граничный случай","крайнего случая","крайние случаи","крайних случаев","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Счастливый путь","text":"Обычный маршрут, когда всё идёт как надо. Хорошее тестирование проверяет и несчастливые пути."},{"id":"perftest","g":"test","word":"Тестирование производительности","text":"Проверка, насколько быстро что-то работает и как справляется с нагрузкой.","also":["тест производительности","тестирования производительности","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Нагрузочное тестирование","text":"Проверка, как система справляется, когда ею пользуется сразу много людей.","also":["нагрузочный тест","нагрузочного тестирования","нагрузочные тесты","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Тестирование безопасности","text":"Поиск слабых мест, которыми кто-то мог бы воспользоваться, чтобы злоупотребить системой или увидеть то, что видеть не должен.","also":["тест безопасности","тестирования безопасности","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Тестирование доступности","text":"Проверка, что людям с разными возможностями удобно пользоваться продуктом, в том числе с программой чтения с экрана или только с клавиатурой.","also":["тест доступности","тестирования доступности","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Линтинг","text":"Автоматическая проверка, которая находит вероятные ошибки и неряшливый стиль в коде, как проверка орфографии для программ.","also":["линтер","линтера","линтеры","линтинга","linting","linter","lint"]},{"id":"static","g":"test","word":"Статический анализ","text":"Автоматический поиск проблем в коде: программа читает код, не запуская его.","also":["статический анализ кода","статического анализа","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Нестабильный тест (flaky)","text":"Тест, который то проходит, то падает без видимой причины, поэтому ему нельзя полностью доверять.","also":["флаки-тест","мигающий тест","нестабильного теста","нестабильные тесты","флаки","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Воспроизведение (repro)","text":"Намеренно заставить баг случиться снова, повторив те же шаги, чтобы его можно было изучить и исправить. Записать эти шаги — самая полезная часть отчёта о баге.","also":["репро","шаги воспроизведения","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Серьёзность","text":"Насколько тяжёлы последствия проблемы: от небольшого неудобства до остановки всего.","also":["критичность","уровень серьёзности","серьёзности","критичности","severity","severity level"]},{"id":"deploy","g":"change","word":"Деплой","text":"Копирование новой версии программы на компьютеры, на которых она работает, например на тестовую копию или на рабочий сервис."},{"id":"release","g":"change","word":"Релиз","text":"Набор готовой работы с названием, который выходит в прод целиком, с короткими заметками о том, что изменилось. 🚀 Релизы пишет заметки по сделанным карточкам.","also":["релизы","выпуск","release"]},{"id":"rollback","g":"change","word":"Откат","text":"Возврат к последней рабочей версии, когда новая создаёт проблемы. В AI-gile «Откат» собирает шаги отмены, записанные в каждом изменении, в один чек-лист.","also":["откатить","роллбэк","rollback"]},{"id":"live","g":"change","word":"Прод","text":"Настоящая версия, которой пользуются люди, в отличие от копии, на которой что-то пробуют. Разработчики говорят «прод» или «продакшн».","also":["продакшн","продакшен","боевая версия","live"],"noTip":1},{"id":"change","g":"change","word":"Изменение","text":"Запланированное изменение в том, на что полагаются люди, сначала описанное: что, зачем, какой риск, когда и как его отменить. Начни с 🔀 Создать изменение.","also":["изменения","запрос на изменение","change request"],"noTip":1},{"id":"risk","g":"change","word":"Риск","text":"То, что может пойти не так, с оценкой: насколько это вероятно и насколько плохо будет. ⚠️ Риски держит их в одном списке, от самой высокой оценки, у каждого есть дата, когда посмотреть снова.","also":["риски","реестр рисков"]},{"id":"chgwin","g":"change","word":"Окно изменений","text":"Время, когда изменения можно выпускать в прод, например спокойный вечер вторника. Вне окна карточку изменения нельзя завершить, если только это не срочный случай.","also":["окна изменений","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Последняя проверка прямо перед выпуском изменения: каждый, кто должен его одобрить, говорит Go или No go. Изменение идёт дальше, только когда все сказали Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Подтверждение","text":"Ожидание «да» перед началом работы. Карточка от друга или изменение ждёт в ✅ Подтверждениях, пока ты не одобришь или не отклонишь его.","also":["подтверждения","одобрение","согласование"]},{"id":"quiettime","g":"change","word":"Тихое время","text":"Отрезок времени, например во время стрима, демо или ночью, когда ничего не выходит в прод. Команды продолжают работать и тестировать, но выпуск ждёт, пока он не закончится. В других местах это называют заморозкой изменений.","also":["тихие часы","заморозка изменений","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Способ работы, при котором те, кто создаёт программы, и те, кто их запускает, работают как одна команда и многое автоматизируют, чтобы изменения выходили часто и безопасно."},{"id":"cicd","g":"change","word":"CI/CD (непрерывная интеграция и поставка)","text":"Изменения всех часто сливаются в основную версию и каждый раз автоматически проверяются (непрерывная интеграция), поэтому программу всегда можно выпустить нажатием кнопки (непрерывная поставка).","also":["непрерывная интеграция","непрерывная поставка","непрерывной интеграции","непрерывной поставки","CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Непрерывное развёртывание","text":"Шаг дальше непрерывной поставки: каждое изменение, прошедшее проверки, само выходит в работу, и нажимать ничего не нужно.","also":["автодеплой","непрерывного развёртывания","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Конвейер (пайплайн)","text":"Автоматическая цепочка шагов, которые проходит изменение на пути в рабочую версию, например сборка, тест, затем развёртывание.","also":["пайплайн","конвейера","пайплайна","пайплайны","пайплайнов","pipeline","pipelines"]},{"id":"environment","g":"change","word":"Окружение","text":"Отдельная копия системы для одной цели, например одна для разработки, одна для тестирования и рабочая.","also":["среда","окружения","окружению","окружении","окружений","среды","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Среда разработки","text":"Копия, в которой работает разработчик, часто на своём компьютере, где сломать что-то никому не повредит.","also":["окружение разработки","среды разработки","среду разработки","dev environment","development environment"]},{"id":"testenv","g":"change","word":"Тестовое окружение","text":"Отдельная копия системы только для тестирования, чтобы не трогать настоящий сервис.","also":["тестовая среда","тестового окружения","тестовой среды","test environment","test environments"]},{"id":"staging","g":"change","word":"Стейджинг","text":"Последняя копия, настроенная точно как рабочая, для финальной проверки перед выходом изменения в работу.","also":["предпродакшен","стейджинга","стейджинге","staging","staging environment"]},{"id":"artifact","g":"change","word":"Артефакт сборки","text":"Файл или пакет, который получается в результате сборки и готов к хранению, проверке или запуску.","also":["артефакты сборки","артефакта сборки","артефакт","артефакты","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Хотфикс","text":"Срочное исправление, которое быстро выпускают вне обычного плана, потому что сломалось что-то важное.","also":["срочное исправление","хотфикса","хотфиксы","хотфиксов","hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Патч","text":"Небольшое обновление, которое исправляет баг или закрывает дыру в безопасности. Быстро ставить патчи безопасности важно.","also":["заплатка","патчи","патча","патчем","патчей","patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Номер версии","text":"Метка вроде 2.4.1, которая говорит, какой у тебя выпуск. Часто первая цифра меняется при больших изменениях, а последняя — при мелких исправлениях.","also":["номера версий","семантическое версионирование","номера версии","номер версии","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Примечания к выпуску","text":"Короткий простой список того, что изменилось в выпуске, для тех, кто им пользуется: исправления и известные ограничения. Ещё это называют чейнджлогом.","also":["список изменений","чейнджлог","примечаний к выпуску","списка изменений","changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Флаг функции (feature flag)","text":"Выключатель для функции: новую работу можно выпустить скрытой и включить (или снова выключить) без нового выпуска.","also":["фича-флаг","переключатель функции","фича-флаги","фича-флага","флага функции","feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Исправление вперёд (roll forward)","text":"Исправить неудачный выпуск, быстро выпустив новую исправленную версию вместо возврата к старой.","also":["откат вперёд","исправления вперёд","roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Канареечный выпуск","text":"Сначала выпустить изменение для небольшой группы, а для всех — только когда всё выглядит нормально. Название пошло от канареек, которых шахтёры брали под землю как ранний сигнал опасности.","also":["канареечное развёртывание","канарейка","канареечного выпуска","канареечный релиз","canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Сине-зелёное развёртывание","text":"Держать две копии рабочей системы и переключать людей на новую разом, чтобы при неудаче сразу переключиться обратно.","also":["сине-зелёного развёртывания","blue-green","blue-green deployment","blue green deployment","blue/green"]},{"id":"zerodown","g":"change","word":"Развёртывание без простоя","text":"Выпуск новой версии так, чтобы сервис ни на минуту не останавливался для пользователей.","also":["без простоя","развёртывания без простоя","zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Управление изменениями","text":"Помощь в том, чтобы изменения проходили успешно: оценить риск, получить нужное согласование и выбрать удачное время.","also":["чейндж-менеджмент","управления изменениями","change enablement","change management"]},{"id":"cab","g":"change","word":"Совет по изменениям (CAB)","text":"Группа, которая рассматривает важные изменения и решает, можно ли их делать и когда.","also":["КАБ","совета по изменениям","CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Стандартное изменение","text":"Малорискованное изменение, которое каждый раз делают одним и тем же проверенным способом, поэтому оно согласовано заранее.","also":["стандартные изменения","стандартного изменения","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Обычное изменение","text":"Изменение, которое нужно проверить и согласовать до того, как оно пойдёт в дело.","also":["нормальное изменение","обычного изменения","обычные изменения","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Экстренное изменение","text":"Изменение, которое нужно сделать немедленно, чтобы исправить или предотвратить серьёзные проблемы; согласование при этом тоже ускоренное.","also":["аварийное изменение","экстренного изменения","экстренные изменения","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Автоматизация","text":"Поручить компьютеру повторяющуюся работу, чтобы она делалась быстрее и каждый раз одинаково.","also":["автоматизировать","автоматизации","автоматизацию","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Инфраструктура","text":"Машины, сети и службы, на которых работает программа.","also":["инфра","инфраструктуры","инфраструктуру","infrastructure","infra"]},{"id":"iac","g":"change","word":"Инфраструктура как код (IaC)","text":"Описание серверов и настроек в файлах, которые хранятся рядом с кодом, чтобы их можно было каждый раз пересоздать точно так же.","also":["инфраструктуры как кода","IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Облако","text":"Аренда компьютеров, хранилища и услуг у большого поставщика через интернет вместо того, чтобы владеть машинами самому.","also":["облачные вычисления","облака","облаку","облаком","облаке","cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Облачный провайдер","text":"Компания, которая сдаёт в аренду вычисления через интернет, например Amazon Web Services (AWS), Microsoft Azure или Google Cloud.","also":["облачные провайдеры","облачного провайдера","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Хостинг","text":"Место, где живёт и работает твоё приложение или сайт, чтобы люди могли до него добраться; обычно его арендуют у компании.","also":["хостить","хостинга","хостингом","хостинге","hosting"]},{"id":"domain","g":"change","word":"Доменное имя","text":"Веб-адрес, который люди вводят, например example.com. Его арендуют на год, поэтому его нужно продлевать.","also":["домен","домены","домена","домену","доменом","домене","доменов","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Сокращение от «система доменных имён»: адресная книга интернета, которая превращает имя вроде example.com в адрес нужного компьютера.","also":["ДНС","система доменных имён","DNS-записи","domain name system"]},{"id":"container","g":"change","word":"Контейнер","text":"Запечатанный пакет с приложением и всем, что ему нужно, чтобы оно работало одинаково на любом компьютере. Самый известный инструмент — Docker.","also":["контейнеры","докер","контейнера","контейнером","контейнере","контейнеров","Docker","container","containers"],"noTip":1},{"id":"vm","g":"change","word":"Виртуальная машина (ВМ)","text":"Виртуальный компьютер, который работает внутри настоящего, так что одна большая машина может работать как несколько.","also":["ВМ","виртуальной машины","виртуальную машину","виртуальные машины","VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Бессерверные вычисления (Serverless)","text":"Запуск кода без того, чтобы самому заниматься серверами: провайдер запускает его, когда нужно, а платишь ты только за фактическое использование."},{"id":"lb","g":"change","word":"Балансировщик нагрузки","text":"Устройство или программа, которая распределяет посетителей между несколькими серверами, чтобы ни один не перегружался.","also":["балансировщик","балансировщика нагрузки","балансировщика","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Кэш","text":"Удобное хранилище недавних результатов под рукой, чтобы одно и то же не приходилось загружать или считать заново. Очистка кэша может помочь, если страницы выглядят устаревшими.","also":["кеш","кэширование","кэша","кэшем","кэше","кеша","cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Сеть доставки контента (CDN)","text":"Всемирный набор серверов с копиями твоих страниц и картинок рядом с посетителями, чтобы всё быстро загружалось.","also":["сети доставки контента","CDN"]},{"id":"migration","g":"change","word":"Миграция","text":"Перенос данных или систем со старого места на новое либо аккуратное изменение устройства базы данных.","also":["миграции","миграция базы данных","миграцию","миграцией","миграций","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Сервис","text":"То, что ты сделал и на что полагаются люди, например сайт или приложение, и за чем присматривают, чтобы оно продолжало работать. Отметь «Этот проект — сервис» и напиши, что он даёт, кто им пользуется и кто дежурит.","also":["сервисы","услуга"]},{"id":"uptimepct","g":"run","word":"Время безотказной работы (uptime)","text":"Какую часть времени услуга работает, обычно в процентах. При 99,9% всё равно набегает около 43 минут простоя в месяц.","also":["аптайм","аптайма","времени безотказной работы","uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Проверка доступности","text":"Автоматическая проверка каждые несколько минут, что твой сервис всё ещё отвечает. Если она несколько раз подряд не проходит, AI-gile сам открывает карточку инцидента.","also":["проверки доступности","проверок доступности","uptime checks","uptime check"]},{"id":"statuspage","g":"run","word":"Страница статуса","text":"Публичная страница, которая показывает, работает ли сервис (зелёный, оранжевый или красный), и последнее обновление, чтобы пользователи могли проверить сами, а не спрашивать.","also":["страницы статуса","статус-страница","status page"]},{"id":"desk","g":"run","word":"Служба поддержки","text":"Место, куда приходят вопросы и сообщения от людей, которые пользуются твоим сервисом. AI-gile относит каждое к запросу, инциденту или идее и подсказывает, если оно похоже на то, о чём уже сообщали.","also":["службы поддержки","поддержка","service desk","help desk","helpdesk","хелпдеск"]},{"id":"svcrequest","g":"run","word":"Запрос на обслуживание","text":"Кто-то просит о чём-то обычном, например новую учётную запись или немного помощи, а не сообщает, что что-то сломалось. Он ждёт своей очереди; инцидент идёт первым.","also":["запросы на обслуживание","запрос"]},{"id":"incident","g":"run","word":"Инцидент","text":"Что-то, что сломалось или работает неправильно для людей, которые пользуются этим прямо сейчас, например сайт лежит или очень тормозит. Карточка 🔥 инцидента идёт без очереди: сначала нужно снова всё запустить.","also":["инциденты","сбой"]},{"id":"major","g":"run","word":"Крупный инцидент","text":"Большой инцидент: затронуто много людей или под угрозой деньги или данные. Одна кнопка бросает на него все команды (рой), будит дежурного и просит обновление статуса каждые 30 минут.","also":["крупные инциденты","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Быть тем, кто отвечает, когда что-то ломается, даже ночью. У каждого сервиса есть дежурный из команды, которого будят первым при его инцидентах.","also":["дежурный","на связи","on call","on-call"]},{"id":"replyby","g":"run","word":"Срок ответа","text":"Сколько карточка может ждать первого ответа, например час для инцидента. Потом у неё появляются красные часы, чтобы ничего тихо не забылось. Ещё это называют целевым временем реакции.","also":["сроки ответа","целевое время реакции"]},{"id":"postmortem","g":"run","word":"Разбор инцидента","text":"Короткий взгляд назад после инцидента: что случилось, что помогло и что изменить, без поиска виноватых. Без него инцидент нельзя закрыть.","also":["пост-мортем","постмортем","post-mortem","разборы инцидентов"]},{"id":"problem","g":"run","word":"Проблема","text":"Скрытая причина одного или нескольких инцидентов. Карточка 🧩 проблемы собирает вместе инциденты, которые повторяются, чтобы найти причину и исправить её насовсем.","also":["проблемы"],"noTip":1},{"id":"rootcause","g":"run","word":"Первопричина","text":"Настоящая причина поломки, а не только то, что было видно со стороны. Исправь первопричину, и инцидент перестанет повторяться.","also":["первопричины","корневая причина","root cause"]},{"id":"workaround","g":"run","word":"Обходной путь","text":"Способ сохранить работу, пока не готово настоящее исправление, например перезапускать то, что зависает. Он записан в карточке проблемы, чтобы никому не пришлось придумывать его заново.","also":["обходные пути","временное решение","воркэраунд","workaround"]},{"id":"knownerror","g":"run","word":"Известная ошибка","text":"Проблема, причина которой понятна, но которая ещё не исправлена, обычно с записанным обходным путём. Раздел 🧩 «Известные ошибки» собирает их, чтобы все пользовались обходным путём и не копали заново.","also":["известные ошибки","known error"]},{"id":"runbook","g":"run","word":"Ранбук","text":"Пошаговая инструкция, как исправить известный вид неполадки, чтобы каждый раз делать это одинаково и быстро. После крупного инцидента команда может предложить ранбук, а ты его одобришь.","also":["ранбуки","runbook","инструкция","регламент"]},{"id":"ci","g":"run","word":"Элемент конфигурации","text":"Одна вещь, от которой зависит твой сервис: например сервер, домен, сертификат, ключ или поставщик. 🗂️ Элементы конфигурации перечисляет их для каждого сервиса, чтобы было видно, что задевает инцидент и что нужно продлить или забэкапить.","also":["элементы конфигурации","элементов конфигурации"]},{"id":"expiry","g":"run","word":"Срок действия","text":"Дата, после которой что-то перестаёт работать, если его не продлить, например сертификат безопасности сайта или его веб-адрес. AI-gile следит за этими датами и за 30 дней создаёт по одной карточке на продление, чтобы ничего не остановилось неожиданно.","also":["сроки действия","истечение срока","контроль сроков"]},{"id":"backup","g":"run","word":"Резервная копия","text":"Сохранённая раньше копия твоих данных, чтобы было к чему вернуться, если что-то потеряется или испортится. AI-gile каждый день делает резервную копию твоих досок.","also":["бэкап","бэкапы","резервные копии","backup"]},{"id":"restore","g":"run","word":"Восстановление","text":"Возврат данных из резервной копии. Копия по-настоящему чего-то стоит, только когда ты знаешь, что из неё можно восстановиться, поэтому иногда стоит это проверять.","also":["восстановить","восстановлено","restore"]},{"id":"svcreview","g":"run","word":"Обзор сервиса","text":"Взгляд назад на один месяц работы сервиса: открытые и исправленные инциденты, как быстро люди получали ответ, доступность и потраченные токены. Ежемесячный обзор показывает это для каждого сервиса.","also":["обзоры сервиса","ежемесячный обзор","ежемесячные обзоры"]},{"id":"accessreview","g":"run","word":"Проверка доступа","text":"Проверка раз в 90 дней: у кого ещё есть доступ — ссылки для общего доступа, роли друзей, сохранённые пароли и ключи. Ты оставляешь или убираешь каждый, чтобы старые доступы не задерживались.","also":["проверки доступа"]},{"id":"improvements","g":"run","word":"Список улучшений","text":"Всё, что команда решила делать лучше, в одном месте: предложения с ретро, действия из разборов и исправления проблем, у каждого свой статус. Ищи в 📈 Улучшения.","also":["списки улучшений","улучшения"]},{"id":"tokencap","g":"run","word":"Лимит токенов","text":"Месячный лимит токенов, которые могут потратить агенты сервиса. На 80% ты получаешь предупреждение; на 100% их фоновая работа ждёт следующего месяца или пока ты не поднимешь лимит.","also":["лимиты токенов","месячный лимит токенов"]},{"id":"svcmgmt","g":"run","word":"Управление услугами","text":"Всё, что нужно, чтобы услуга оставалась полезной и работала для тех, кто на неё полагается, изо дня в день.","also":["управление сервисом","управления услугами","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Широко используемое руководство по хорошему управлению услугами: инциденты, проблемы, изменения и многое другое. Название когда-то расшифровывалось как IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Управление ИТ-услугами (ITSM)","text":"Работа с технологиями как с услугой для людей, с понятными способами обрабатывать запросы, инциденты, изменения и улучшения.","also":["управления ИТ-услугами","ITSM","IT service management"]},{"id":"managed","g":"run","word":"Управляемая услуга","text":"Услуга, которую для тебя запускает и обслуживает кто-то другой по договорённости о том, насколько хорошо она должна работать.","also":["управляемые услуги","управляемой услуги","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Владелец услуги","text":"Человек, который отвечает за услугу в целом: как хорошо она работает, чего стоит и как улучшается.","also":["владельцы услуг","владельца услуги","service owner","service owners"]},{"id":"sla","g":"run","word":"Соглашение об уровне услуг (SLA)","text":"Письменное обещание клиентам, как хорошо будет работать услуга, например «доступна 99,9% времени» или «ответ в течение часа», часто с возвратом денег, если обещание нарушено.","also":["СЛА","соглашения об уровне услуг","SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Цель по уровню услуг (SLO)","text":"Собственная цель команды, как хорошо услуга должна работать за период; её обычно ставят чуть строже, чем в SLA, для запаса.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Показатель уровня услуг (SLI)","text":"Реальное измерение, которое сверяют с целью, например доля посещений, при которых всё загрузилось нормально.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Доступность (availability)","text":"Могут ли люди пользоваться услугой, когда она им нужна; часто измеряется временем безотказной работы.","also":["высокая доступность","availability","high availability"]},{"id":"downtime","g":"run","word":"Простой (downtime)","text":"Время, когда услуга не работает или отключена, по плану или внезапно.","also":["даунтайм","простоя","простои","простоев","downtime","down time"]},{"id":"errorbudget","g":"run","word":"Бюджет ошибок","text":"Небольшой объём сбоев, который допускает твоя цель по надёжности. Пока он не исчерпан, можно рисковать с изменениями; когда закончился — нужно притормозить.","also":["бюджета ошибок","бюджет ошибок","error budget","error budgets"]},{"id":"outage","g":"run","word":"Авария","text":"Время, когда услуга для пользователей не работает или работает с серьёзными сбоями.","also":["аварии","аварию","аварий","outage","outages"]},{"id":"degraded","g":"run","word":"Деградация услуги","text":"Работает, но плохо: медленно или с частью неработающих функций.","also":["работает с ухудшением","деградации","деградация","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Мониторинг","text":"Постоянное автоматическое наблюдение за услугой, чтобы проблемы замечали, в идеале раньше пользователей.","also":["мониторинга","мониторингом","мониторинге","monitoring"]},{"id":"observability","g":"run","word":"Наблюдаемость","text":"Насколько хорошо по журналам, числам и трассировкам можно понять снаружи, что происходит внутри системы.","also":["наблюдаемости","observability","o11y"]},{"id":"log","g":"run","word":"Журнал (лог)","text":"Дневник, который программа ведёт о том, что она делает; по нему выясняют, что пошло не так.","also":["лог","логи","журналы","лога","логах","логов","журнала","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Трассировка","text":"Запись того, как один запрос шаг за шагом проходит через разные части системы; видно, где он замедлился.","also":["трейс","трассировки","трейсы","трейсов","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Задержка (latency)","text":"Сколько времени уходит на ответ, например ожидание между нажатием и появлением страницы.","also":["латентность","латентности","latency"]},{"id":"alert","g":"run","word":"Оповещение (алерт)","text":"Автоматическое сообщение о том, что что-то требует внимания, например сайт не отвечает.","also":["алерт","алерты","оповещения","оповещение","оповещений","алертов","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Усталость от оповещений","text":"Когда оповещений так много, что люди перестают на них обращать внимание, в том числе на важные.","also":["усталости от оповещений","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Дашборд","text":"Экран, на котором самые важные числа и состояния видны с одного взгляда.","also":["панель мониторинга","приборная панель","дашборда","дашборде","дашбордов","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Вызов дежурного (paging)","text":"Срочный вызов дежурного из-за проблемы, даже если его приходится будить.","also":["пейджинг","вызова дежурного","вызов дежурного","paging","paged"]},{"id":"escalation","g":"run","word":"Эскалация","text":"Подключение того, у кого больше умения или полномочий, когда вопрос нельзя решить на текущем уровне или недостаточно быстро.","also":["эскалировать","эскалации","эскалацию","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Сортировка (триаж)","text":"Быстрая сортировка поступающих вопросов по срочности и важности, чтобы самыми серьёзными занялись в первую очередь.","also":["триаж","триажа","triage","triaged"]},{"id":"impact","g":"run","word":"Влияние (impact)","text":"Насколько что-то затрагивает людей: сколько их и насколько сильно.","noTip":1},{"id":"urgency","g":"run","word":"Срочность","text":"Как быстро нужно заняться вопросом. Влияние и срочность вместе определяют приоритет.","noTip":1},{"id":"plevels","g":"run","word":"Уровни приоритета (P1, P2…)","text":"Метки, показывающие, насколько срочен вопрос. P1 — самый серьёзный, действовать нужно немедленно.","also":["уровня приоритета","уровней приоритета","P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Очередь тикетов","text":"Список запросов и инцидентов, ожидающих, пока их возьмут в работу.","also":["очереди тикетов","очередь тикетов","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Первая и вторая линия","text":"Уровни поддержки: первая линия принимает звонок и решает простое, у второй линии более глубокие знания для сложного. Их ещё называют tier 1 и tier 2.","also":["первая линия","вторая линия","поддержка первой линии","первой линии","второй линии","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Руководитель инцидента","text":"Один человек, который руководит реакцией на инцидент, чтобы все знали, кто решает и кто что делает.","also":["командир инцидента","руководителя инцидента","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Время реакции","text":"Сколько проходит времени, прежде чем кто-то впервые возьмёт запрос или инцидент в работу.","also":["время отклика","времени реакции","response time","response times"]},{"id":"resolution","g":"run","word":"Время решения","text":"Сколько времени уходит на то, чтобы полностью разобраться с запросом или инцидентом: от сообщения до исправления.","also":["время устранения","времени решения","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Среднее время восстановления (MTTR)","text":"Сколько в среднем уходит времени, чтобы снова запустить услугу после поломки. MTTR могут понимать немного по-разному, поэтому говори, что именно ты измеряешь.","also":["среднего времени восстановления","MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Среднее время между отказами (MTBF)","text":"Сколько в среднем услуга работает, прежде чем что-то сломается.","also":["среднего времени между отказами","MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"База данных конфигураций (CMDB)","text":"Список всех элементов конфигурации и того, как они связаны, чтобы видеть, что от чего зависит.","also":["базы данных конфигураций","CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Актив","text":"Всё ценное, чем ты владеешь или за что платишь, чтобы услуга работала: ноутбук, лицензия на программу или домен.","also":["активы","актива","активом","активов","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Планирование мощностей","text":"Забота о том, чтобы вычислительной мощности, места для хранения и людей хватило на то, что впереди.","also":["план мощностей","планирования мощностей","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Масштабирование","text":"Справляться с ростом числа пользователей, добавляя машине мощности (вертикальное масштабирование) или добавляя больше машин (горизонтальное).","also":["масштабировать","масштабирования","масштабированием","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Непрерывность бизнеса","text":"Планы на то, чтобы важное продолжало работать, когда случается что-то крупное, например потеря офиса, ключевого поставщика или компьютеров.","also":["план непрерывности бизнеса","непрерывности бизнеса","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Аварийное восстановление (DR)","text":"План и средства, чтобы вернуть услугу в строй после чего-то серьёзного, например потери целого центра обработки данных.","also":["восстановление после сбоя","аварийного восстановления","DR","disaster recovery"]},{"id":"rto","g":"run","word":"Целевое время восстановления (RTO)","text":"Самое долгое время, которое услуга может простаивать после катастрофы, прежде чем она должна снова заработать.","also":["целевого времени восстановления","RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Целевая точка восстановления (RPO)","text":"Сколько последних данных можно позволить себе потерять, в единицах времени. RPO в один час означает резервные копии не реже раза в час.","also":["целевой точки восстановления","RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Резервирование","text":"Запас наготове, например второй сервер, чтобы один отказ не остановил услугу.","also":["избыточность","резервирования","избыточности","redundancy"]},{"id":"failover","g":"run","word":"Автопереключение (failover)","text":"Автоматическое переключение на запасную систему, когда обычная отказала.","also":["фейловер","автопереключения","автопереключение","failover","fail over"]},{"id":"spof","g":"run","word":"Единая точка отказа","text":"Одна часть, поломка которой тянет за собой всё, потому что запасной нет.","also":["единой точки отказа","единая точка отказа","SPOF","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Окно обслуживания","text":"Запланированное время, когда услугу могут приостановить или замедлить ради обслуживания; пользователей предупреждают заранее.","also":["плановые работы","окна обслуживания","окно обслуживания","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Передача дел","text":"Передача работы, знаний и ответственности другому человеку или команде, чтобы ничего не потерялось.","also":["хендовер","передачи дел","передачу дел","handover","handovers"]},{"id":"kb","g":"run","word":"База знаний","text":"Собрание справочных статей и ответов для пользователей и для команды.","also":["базы знаний","базу знаний","базе знаний","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Удовлетворённость клиентов (CSAT)","text":"Оценка от пользователей, насколько они остались довольны; её часто спрашивают после закрытия запроса.","also":["удовлетворённости клиентов","CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Поставщик","text":"Сторонняя компания, на которую ты полагаешься, например твой хостинг-провайдер. Ещё её называют вендором или третьей стороной.","also":["поставщики","вендор","вендоры","третья сторона","поставщика","поставщику","поставщиком","поставщиков","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Вывод услуги из эксплуатации","text":"Навсегда и безопасно отключить услугу: предупредить её пользователей, разобраться с её данными и доступом и прекратить расходы на неё.","also":["закрытие услуги","вывода из эксплуатации","вывод из эксплуатации","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Конец жизненного цикла (EOL)","text":"Когда производитель перестаёт выпускать для продукта обновления и поддерживать его, и его пора заменить.","also":["конца жизненного цикла","EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Кибербезопасность","text":"Защита систем и данных от взлома, кражи и повреждения.","also":["информационная безопасность","кибербезопасности","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Аутентификация","text":"Проверка того, кто перед тобой, обычно по паролю или коду. Часто сокращается до authn.","also":["аутентификации","аутентификацию","authn","authentication"]},{"id":"authz","g":"sec","word":"Авторизация","text":"Проверка того, что человеку разрешено делать, когда уже известно, кто он. Часто сокращается до authz.","also":["авторизации","авторизацию","authz","authorisation","authorization"]},{"id":"mfa","g":"sec","word":"Многофакторная аутентификация (MFA)","text":"Вход с двумя или более подтверждениями, например пароль и код на телефоне. Ещё это называют двухфакторной аутентификацией (2FA).","also":["двухфакторная аутентификация","многофакторной аутентификации","двухфакторной аутентификации","MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Единый вход (SSO)","text":"Войти один раз и попасть во многие системы, например использовать рабочую учётную запись везде.","also":["единого входа","единый вход","SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Менеджер паролей","text":"Приложение, которое придумывает надёжные пароли и запоминает их за тебя.","also":["менеджеры паролей","менеджера паролей","менеджером паролей","password manager","password managers"]},{"id":"secret","g":"sec","word":"Секрет","text":"Пароль, ключ или другой закрытый код, который программа использует, чтобы получить к чему-то доступ. Его нельзя никому передавать и нельзя записывать в код.","also":["секреты","секрета","секретов","секретами","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API-ключ","text":"Секретный код, который позволяет программе пользоваться API другой службы и показывает, кто пользуется (и платит).","also":["ключ API","API-ключа","API-ключи","API-ключей","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Токен доступа","text":"Временный пропуск, который подтверждает, что программе можно войти, поэтому пароль каждый раз не нужен. Не путай с токенами ИИ.","also":["токены доступа","токена доступа","токенов доступа","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Шифрование","text":"Превращение информации в «кашу», которую может прочитать только тот, у кого есть нужный ключ.","also":["зашифровано","шифровать","шифрования","шифрованием","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Безопасный способ, которым веб-страницы доходят до тебя; его показывает замочек в браузере. По пути никто не может их прочитать или изменить."},{"id":"cert","g":"sec","word":"SSL/TLS-сертификат","text":"Цифровое удостоверение, с помощью которого сайт доказывает, кто он, и может работать по HTTPS. Срок его действия истекает, поэтому его нужно продлевать.","also":["TLS-сертификат","SSL-сертификат","сертификат","сертификаты","сертификата","сертификатов","сертификатом","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Права доступа","text":"Правила о том, кто что может видеть или менять.","also":["разрешения","прав доступа","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Принцип наименьших привилегий","text":"Давать каждому человеку или программе только тот доступ, который им действительно нужен, и только на то время, пока он нужен.","also":["минимум прав","наименьших привилегий","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Ролевое управление доступом (RBAC)","text":"Выдавать доступ по ролям, например «наблюдатель» или «редактор», а не по отдельным людям.","also":["ролевой доступ","ролевого управления доступом","RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Уязвимость","text":"Слабое место, которым кто-то может воспользоваться, чтобы взломать систему или навредить.","also":["уязвимости","уязвимость","уязвимостью","уязвимостей","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (уязвимость нулевого дня)","text":"Слабое место, о котором злоумышленники знают раньше, чем у создателей было время его исправить.","also":["нулевой день","зеродей","уязвимости нулевого дня","zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Вредоносное ПО","text":"Вредоносные программы, например вирусы, созданные, чтобы портить, шпионить или красть.","also":["малварь","вредоносного ПО","вредоносные программы","malware"]},{"id":"ransomware","g":"sec","word":"Шифровальщик (ransomware)","text":"Вредоносная программа, которая блокирует твои файлы и требует деньги за разблокировку. Лучшая защита — хорошие резервные копии.","also":["программа-вымогатель","вымогатель","шифровальщика","шифровальщики","вымогателя","ransomware","ransomware attack"]},{"id":"phishing","g":"sec","word":"Фишинг","text":"Поддельные сообщения, которые пытаются обманом выманить пароли или деньги или заставить открыть что-то опасное.","also":["фишинговое письмо","фишинговые письма","фишинга","фишингом","phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Социальная инженерия","text":"Обман людей, а не компьютеров, чтобы получить доступ, например фальшивый звонок «из техподдержки»."},{"id":"firewall","g":"sec","word":"Брандмауэр (файрвол)","text":"Охранник, который решает, какой сетевой трафик можно впускать и выпускать.","also":["файрвол","межсетевой экран","брандмауэра","файрвола","брандмауэр","firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Сокращение от «виртуальная частная сеть»: закрытое, зашифрованное соединение через интернет, которое часто используют, чтобы безопасно попасть в рабочие системы.","also":["ВПН","виртуальная частная сеть","virtual private network","VPN"]},{"id":"ddos","g":"sec","word":"Отказ в обслуживании (DoS, DDoS)","text":"Заваливание услуги таким количеством ненастоящего трафика, что настоящие люди не могут ею пользоваться. DDoS значит, что трафик идёт сразу со многих компьютеров.","also":["ДДоС","DDoS-атака","отказа в обслуживании","DDoS-атаки","DDoS-атак","DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Тест на проникновение (пентест)","text":"Наём дружественных экспертов, которые пытаются взломать систему, чтобы слабые места нашлись раньше, чем их найдут настоящие злоумышленники.","also":["пентест","пентеста","пентесты","теста на проникновение","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Аудит безопасности","text":"Тщательная проверка, насколько хорошо что-то защищено, по списку надёжных практик.","also":["аудиты безопасности","аудита безопасности","аудита","аудит","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Моделирование угроз","text":"Продумывание того, кто может напасть на систему, как и что ты сделаешь, чтобы их остановить.","also":["модель угроз","моделирования угроз","модели угроз","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Утечка данных","text":"Когда личная информация попадает к тем, у кого её быть не должно, либо теряется или меняется без разрешения.","also":["утечки данных","утечку данных","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Персональные данные","text":"Любые сведения о человеке, которого можно опознать, например имя, адрес электронной почты или местонахождение. Ещё это называют PII.","also":["персональных данных","персональными данными","PII","personal data","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Европейский закон о персональных данных (в Великобритании своя версия): собирай только то, что нужно, храни в безопасности и давай людям смотреть свои данные и удалять их.","also":["ОРЗД","Общий регламент по защите данных","General Data Protection Regulation","GDPR"]},{"id":"dataprot","g":"sec","word":"Защита данных","text":"Бережное обращение с персональными данными, в рамках закона.","also":["закон о защите данных","защиты данных","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Политика конфиденциальности","text":"Открытая страница о том, какие персональные данные ты собираешь, зачем и что с ними делаешь.","also":["политика приватности","политики конфиденциальности","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Согласие","text":"Ясное и добровольное «да» человека на то, чтобы его данные использовали определённым образом. Его можно забрать обратно в любой момент.","also":["согласия","согласием","opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (куки)","text":"Маленький файл, который сайт сохраняет в твоём браузере, чтобы запоминать разное, например что вход уже выполнен. Для некоторых сначала нужно твоё согласие.","also":["куки","куках","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Минимизация данных","text":"Собирать и хранить только те персональные данные, которые действительно нужны для дела.","also":["минимизации данных","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Срок хранения данных","text":"Как долго данные хранятся, прежде чем их удалят. Хранить их не дольше необходимого безопаснее, и часто этого требует закон.","also":["хранение данных","срока хранения данных","сроки хранения","data retention","retention period"]},{"id":"anon","g":"sec","word":"Анонимизация","text":"Изменение данных так, чтобы по ним больше нельзя было разумно определить, о ком речь.","also":["анонимизированные данные","анонимные данные","анонимизации","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Псевдонимизация","text":"Замена имён и других сведений кодами; ключ, по которому их можно сопоставить, хранится отдельно. Это по-прежнему персональные данные.","also":["псевдонимизированные данные","псевдонимизации","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Соглашение об обработке данных (DPA)","text":"Договор о том, как поставщик может обращаться с персональными данными от твоего имени.","also":["соглашения об обработке данных","DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Оценка воздействия на защиту данных (DPIA)","text":"Тщательный взгляд до начала работы на то, как план использования персональных данных может повлиять на людей и как снизить риски.","also":["оценки воздействия на защиту данных","DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Журнал аудита","text":"Запись о том, кто что сделал и когда, чтобы действия можно было проверить позже.","also":["журналы аудита","журнала аудита","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Соответствие требованиям (комплаенс)","text":"Соблюдение законов, правил и стандартов, которые к тебе относятся, и умение это показать.","also":["комплаенс","соответствия требованиям","комплаенса","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Известный международный стандарт управления информационной безопасностью. Компании могут проходить по нему сертификацию.","also":["ИСО 27001","ISO/IEC 27001","ISO 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Американский отчёт, проверенный внешними аудиторами, который показывает, что компания надлежащим образом заботится о данных клиентов.","also":["SOC2","SOC 2"]},{"id":"agent","g":"ai","word":"Агент","text":"ИИ, который сам работает над задачей: читает код, вносит изменения, запускает проверки и докладывает. Его работу всё равно проверяют.","also":["агенты","агента","агентов","агенту","агентом"]},{"id":"token","g":"ai","word":"Токен","text":"Небольшие кусочки текста, которые ИИ читает и пишет, примерно три четверти слова каждый. Использование ИИ считают в токенах, так что чем их меньше, тем больше остаётся от твоего тарифа.","also":["токены","токена","токенов","токенов","токену"]},{"id":"hook","g":"ai","word":"Хук","text":"Небольшая команда, которая сама запускается в заданный момент, например когда начинается ИИ-сессия, чтобы команда слышала твои комментарии.","also":["хуки","хука","хуков"]},{"id":"ai","g":"ai","word":"Искусственный интеллект (ИИ)","text":"Компьютерные системы, которые делают то, что мы обычно считаем делом человека: пишут, отвечают на вопросы, узнают картинки.","also":["ИИ","нейросеть","нейросети","искусственного интеллекта","искусственный интеллект","нейросетей","AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Машинное обучение (ML)","text":"Способ научить компьютеры находить закономерности по множеству примеров, а не давать им точные правила.","also":["МО","машинного обучения","машинное обучение","ML","machine learning"]},{"id":"model","g":"ai","word":"Модель","text":"Обученный «мозг» ИИ-системы, созданный на огромном числе примеров. Модели различаются умениями, скоростью и ценой.","also":["модели","ИИ-модель","моделью","моделей","моделям","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Большая языковая модель (LLM)","text":"ИИ-модель, обученная на огромном количестве текстов, поэтому она умеет читать и писать на языке людей.","also":["БЯМ","языковая модель","большой языковой модели","языковые модели","языковых моделей","LLM","LLMs"]},{"id":"genai","g":"ai","word":"Генеративный ИИ","text":"ИИ, который создаёт новое, например текст, картинки или код, а не только сортирует или распознаёт.","also":["генеративный искусственный интеллект","генеративного ИИ","GenAI","Generative AI"]},{"id":"chatbot","g":"ai","word":"Чат-бот","text":"Программа, с которой разговаривают обычным языком, печатая или говоря.","also":["чат-боты","чатбот","чат-бота","чат-ботом","чат-ботов","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Промпт","text":"То, что ты даёшь ИИ: твой вопрос или указания и всё, что ты ему передаёшь. Чем яснее промпт, тем обычно лучше ответ.","also":["запрос к ИИ","промпты","промпта","промптом","промпте","промптов","prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Промпт-инжиниринг","text":"Умение писать промпты, которые дают надёжный и полезный результат.","also":["составление промптов","промпт-инжиниринга","prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Системный промпт","text":"Фоновые указания, которые ИИ получает до начала разговора: они задают его роль и правила. У них больший вес, чем у того, что ты печатаешь.","also":["системные промпты","системная инструкция","системного промпта","системном промпте","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Контекст","text":"Всё, что ИИ видит, пока работает: указания, твои сообщения, прочитанные файлы и прежние ответы.","noTip":1},{"id":"ctxwin","g":"ai","word":"Контекстное окно","text":"Сколько ИИ может держать в уме одновременно, измеряется в токенах. Всё, что за этим пределом, отбрасывается или сжимается.","also":["контекстные окна","контекстного окна","контекстном окне","context window","context windows"]},{"id":"session","g":"ai","word":"Сессия","text":"Один рабочий разговор с ИИ от начала до конца. Новая сессия начинается со свежей памяти.","also":["сессии","сессию","сессией","сессий","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Память","text":"Заметки, которые ИИ хранит между сессиями, чтобы помнить твои предпочтения и прежние решения.","noTip":1},{"id":"hallucination","g":"ai","word":"Галлюцинация","text":"Когда ИИ говорит что-то уверенно, но на самом деле выдуманное или неверное. Важные факты проверяй.","also":["галлюцинации","галлюцинировать","галлюцинацию","галлюцинаций","галлюцинирует","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Обучение","text":"Обучение модели на огромном числе примеров до того, как ею начнут пользоваться.","also":["обучать","обученный","обучения","обучением","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Обучающие данные","text":"Примеры, на которых модель училась. Её знания заканчиваются на дате, когда эти данные были собраны.","also":["обучающая выборка","обучающих данных","training data","training set"]},{"id":"cutoff","g":"ai","word":"Дата отсечки знаний","text":"Дата, на которой заканчиваются встроенные знания ИИ. О более поздних событиях он не знает, пока не найдёт их сам.","also":["отсечка знаний","отсечки знаний","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Дообучение (fine-tuning)","text":"Дополнительное обучение готовой модели на твоих примерах, чтобы она лучше справлялась с одним конкретным делом.","also":["файнтюнинг","дообучить","дообучения","дообучение","файнтюнинга","fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Инференс","text":"Когда ИИ-модель по-настоящему используют, чтобы ответить на что-то, в отличие от её обучения.","also":["вывод модели","инференса","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Использование инструментов","text":"Когда ИИ может не только говорить, но и делать: запускать команды, читать файлы или искать в интернете через инструменты, которые ему даёт приложение.","also":["вызов инструментов","использования инструментов","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Субагент","text":"ИИ-помощник, которому главный ИИ поручает небольшую работу и получает от него результат.","also":["субагенты","субагента","субагенту","субагентов","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Мультиагентная система","text":"Несколько ИИ работают вместе над одним делом, у каждого своя часть, как в маленькой команде.","also":["мультиагент","мультиагентной системы","мультиагентные системы","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Автономность","text":"Сколько ИИ может делать сам, прежде чем ему придётся спросить человека.","also":["автономности","автономии","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Человек в контуре","text":"Участие человека, который проверяет или одобряет действия ИИ в ключевых местах. В AI-gile это ты.","also":["человек в цикле","человека в контуре","human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Ограничители (guardrails)","text":"Пределы и проверки, которые не дают действиям ИИ стать опасными, например одобрение перед выпуском чего-либо. Они снижают риск ошибок, но не исключают их.","also":["защитные ограждения","ограничителей","ограничители","guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Генерация с дополнением поиском (RAG)","text":"Позволить ИИ заглянуть в твои документы, прежде чем он ответит, чтобы его ответы опирались на твои факты.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Эмбеддинг","text":"Превращение текста в список чисел, передающий его смысл, чтобы компьютер мог находить близкие по смыслу вещи.","also":["эмбеддинги","эмбеддинга","эмбеддингов","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Векторная база данных","text":"База данных, созданная для поиска по таким спискам чисел (эмбеддингам), чтобы находить материалы с похожим смыслом.","also":["векторные базы данных","векторной базы данных","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Общий способ подключать инструменты и источники данных к ИИ-приложениям, чтобы ИИ мог ими пользоваться.","also":["протокол контекста модели","MCP-сервер","MCP-серверы","MCP"]},{"id":"temperature","g":"ai","word":"Температура","text":"Настройка того, насколько смелыми будут ответы ИИ. Низкая даёт более ровные и предсказуемые ответы, высокая — более разнообразные. Ни то ни другое не гарантирует, что он всегда прав.","also":["температура модели","температуры","температуру","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Мультимодальность","text":"Умение работать с несколькими видами информации, например с текстом, картинками и звуком.","also":["мультимодальный","мультимодальности","мультимодальная","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Оценка (eval)","text":"Запланированная проверка, насколько хорошо ИИ справляется с выбранными примерами, чтобы сравнивать модели или промпты.","also":["эвал","эвалы","эвалов","eval","evals","evaluation"]},{"id":"bias","g":"ai","word":"Предвзятость","text":"Когда ИИ (или человек) несправедливо склоняется в одну сторону, часто из-за того, на чём он учился.","also":["смещение","предвзятости","предвзятость","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Ответственный ИИ","text":"Использование ИИ честно, безопасно и справедливо, когда за результаты по-прежнему отвечают люди.","also":["этичный ИИ","ответственного ИИ","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Инъекция промпта","text":"Трюк, когда скрытые указания на веб-странице или в файле пытаются заставить ИИ сделать то, чего его пользователь не просил.","also":["промпт-инъекция","инъекции промпта","промпт-инъекции","prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Лимит запросов","text":"Ограничение на то, сколько запросов можно отправить службе за заданное время. Превысишь его — придётся подождать.","also":["рейт-лимит","лимита запросов","лимиты запросов","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Лимит использования","text":"Сколько ИИ-работы разрешает твой тариф за период; после этого она приостанавливается или стоит дороже.","also":["лимиты использования","лимита использования","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Вайб-кодинг","text":"Создание программ в основном так: ты описываешь ИИ, чего хочешь, а он пишет код.","also":["вайбкодинг","вайб-кодинга","vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Бюджет","text":"Сумма денег, выделенная на что-то.","also":["бюджеты","бюджета","бюджету","бюджетом","бюджете","бюджетов","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Оценка стоимости","text":"Прикидка того, сколько что-то будет стоить, сделанная до начала работы.","also":["смета","оценки стоимости","сметы","смету","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Возврат инвестиций (ROI)","text":"Сколько ты получаешь по сравнению с тем, сколько вкладываешь. Если результат положительный, оно того стоило.","also":["окупаемость","возврата инвестиций","окупаемости","ROI"]},{"id":"tco","g":"money","word":"Совокупная стоимость владения (TCO)","text":"Всё, чего что-то действительно стоит за всё время жизни, а не только цена покупки: эксплуатация, поддержка, обновления и, наконец, вывод из работы.","also":["совокупной стоимости владения","TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx и OpEx","text":"CapEx — деньги, потраченные сразу на то, что остаётся у тебя; OpEx — постоянные траты, например ежемесячные счета.","also":["капитальные затраты","операционные затраты","капитальных затрат","операционных затрат","CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Подписка","text":"Регулярная оплата, обычно раз в месяц или год, чтобы продолжать чем-то пользоваться.","also":["подписки","подписку","подписке","подпиской","подписок","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"ПО как услуга (SaaS)","text":"Программа, которой ты пользуешься онлайн и платишь за неё подпиской, а запускает её для тебя создатель.","also":["софт как сервис","SaaS"]},{"id":"payg","g":"money","word":"Оплата по факту использования","text":"Платишь только за то, чем пользуешься, как при облачных вычислениях или ИИ-токенах.","also":["плати за использование","оплаты по факту использования","pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Превышение лимита","text":"Использование сверх того, что включает твой тариф; за него могут взять дополнительную плату.","also":["перерасход","превышения лимита","перерасхода","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Оповещение о расходах","text":"Сообщение, когда траты или использование достигают выбранного тобой уровня. Оно предупреждает, но не всегда останавливает дальнейшие списания.","also":["оповещения о расходах","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Бесплатный уровень","text":"Бесплатный уровень платной услуги, с ограничениями. Удобен, чтобы начать.","also":["бесплатный тариф","бесплатного уровня","бесплатного тарифа","free tier","free plan"]},{"id":"pricing","g":"money","word":"Тарифный план","text":"Разные пакеты, которые продаёт услуга, у каждого своя цена и свои ограничения.","also":["тарифные планы","тариф","тарифы","тарифного плана","тарифа","тарифом","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Лицензия","text":"Правила того, как можно использовать, копировать, менять или распространять то, что сделал кто-то другой: программу, шрифты или картинки.","also":["лицензии","лицензию","лицензией","лицензий","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Открытый исходный код (open source)","text":"Программы, код которых любой может читать, использовать и часто менять бесплатно, по правилам их лицензии.","also":["опенсорс","открытый код","открытого исходного кода","открытого кода","опенсорса","open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Лицензия открытого кода","text":"Правила, которые идут с открытым кодом. Одни разрешают почти всё (как MIT), другие просят делиться и твоими изменениями (как GPL).","also":["лицензии открытого кода","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Проприетарное ПО","text":"Принадлежит компании, и его нельзя свободно копировать или менять. Противоположность открытому коду.","also":["проприетарный","проприетарного ПО","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Авторское право","text":"Закреплённое законом право автора решать, кто и как может копировать его работы, в том числе код и тексты.","also":["копирайт","авторского права","авторские права","copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Интеллектуальная собственность (IP)","text":"Идеи и творения, которые закон считает чьей-то собственностью: код, дизайн, названия и логотипы.","also":["интеллектуальная собственность","интеллектуальной собственности","IP","intellectual property"]},{"id":"tos","g":"money","word":"Условия использования","text":"Правила, с которыми ты соглашаешься, когда пользуешься услугой.","also":["пользовательское соглашение","условий использования","пользовательского соглашения","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Договор","text":"Письменное соглашение между двумя сторонами, которое защищает закон.","also":["контракт","договоры","контракты","договора","договору","договором","договоре","договоров","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Техническое задание (SOW)","text":"Документ, в котором точно описано, какая работа будет сделана, к какому сроку и за какую цену.","also":["ТЗ","технического задания","SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Фиксированная цена","text":"Согласованная цена за всю работу, как бы долго она ни длилась.","also":["фиксированная стоимость","фиксированной цены","фиксированную цену","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Оплата по затратам (Time and Materials)","text":"Платишь за реально отработанные часы и реально использованные материалы, а не за заранее назначенную цену.","also":["оплата по часам","оплаты по затратам","T&M","time and materials"]},{"id":"invoice","g":"money","word":"Счёт","text":"Документ с просьбой оплатить сделанную работу или поставленный товар.","also":["счёт-фактура","инвойс","счета","счёта","счету","счетов","инвойса","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Привязка к поставщику (vendor lock-in)","text":"Когда уйти от поставщика так трудно или дорого, что ты застреваешь у него.","also":["лок-ин","зависимость от поставщика","привязки к поставщику","vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Закупки","text":"Процесс выбора поставщиков и покупки у них.","also":["закупка","снабжение","закупок","закупкам","procurement"]},{"id":"servicecredit","g":"money","word":"Компенсация по SLA (service credit)","text":"Деньги назад или скидка, которые ты получаешь, когда поставщик не выполняет SLA.","also":["сервисный кредит","компенсация по SLA","сервисного кредита","компенсации по SLA","service credit","service credits"]}]}};
